export const ngoPrompts = [
  {"id":"ngo-1","title":"Community Foundation Program Narrative","prompt":"You are the grants manager at an urban literacy nonprofit in Chicago that runs after-school reading programs for 800 students across 12 low-income elementary schools on the South Side. You are applying to the Chicago Community Trust for a $120,000 two-year grant to expand your volunteer tutor training program. Write the complete program narrative (maximum 1,500 words) in CCT application format: open with a statement of need citing specific Chicago third-grade reading proficiency data and connecting to the Trust's Education priority area; describe your evidence-based tutoring model influenced by Reading Recovery and structured literacy research; state measurable outcomes for the grant period (number of tutors trained, average student reading level gains in Lexile scores); outline your evaluation plan using pre/post Fountas and Pinnell assessments administered by an independent literacy coach; and close with a sustainability narrative explaining how you will fund the program after the grant through Chicago Public Schools partnership fees. Write in a community-centered, outcome-focused tone that is honest about the challenge of volunteer retention.","tags":["grant-writing","community-foundation","program-narrative","literacy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
  {"id":"ngo-2","title":"Ford Foundation BUILD Letter of Inquiry","prompt":"You are the Development Director at a 15-person environmental justice nonprofit in Detroit that works with frontline communities living within one mile of petrochemical facilities in the 48217 zip code — one of the most polluted zip codes in Michigan. You are preparing a Letter of Inquiry to the Ford Foundation's BUILD program, which offers general operating support grants of $300,000–$500,000 over three years. Write a two-page LOI (maximum 750 words) that: introduces your organization's theory of change connecting air quality monitoring data to zoning policy reform; describes two specific policy wins from the past three years; explains why general operating support rather than project funding would accelerate your impact; and articulates how your work connects to Ford's Civic Engagement and Government priority. Write for a program officer who reads 40 LOIs per week — be specific, not inspirational.","tags":["grant-writing","ford-foundation","letter-of-inquiry","environmental-justice"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-3","title":"HHS Youth Homelessness Federal Grant Narrative","prompt":"You are the Program Director at a 30-staff homeless services nonprofit in Seattle that operates a 24-bed emergency shelter and street outreach program for youth aged 18–24. You are writing the Project Narrative for a U.S. Department of Health and Human Services Youth Homelessness Demonstration Program (YHDP) grant requesting $800,000 over two years. Write the Project Narrative (maximum 3,000 words) covering: Statement of Need (cite the 2023 Seattle/King County Point-in-Time count data and the disproportionate representation of LGBTQ+ youth); Project Description (explain your Housing First approach and trauma-informed care model, and coordinated entry system integration); Evaluation Plan (how you will track housing placement rates, length of stay, and recidivism using HMIS data); and Organizational Capacity (staff credentials, existing partnerships with DESC and YouthCare, and your compliance record on prior federal grants). Match the formal, evidence-heavy tone required for federal reviewers scoring on NOFO criteria.","tags":["grant-writing","federal-grant","HHS","youth-homelessness","housing-first"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-4","title":"MacArthur 100&Change Concept Paper","prompt":"You are the Executive Director of a 20-year-old maternal health nonprofit in rural Mississippi that has developed a community health worker model demonstrably reducing Black maternal mortality rates in Leflore and Sunflower counties by 34% over five years, with a peer-reviewed evaluation by the University of Mississippi Medical Center. You are preparing the concept paper for MacArthur Foundation's 100&Change competition, which awards a single $100 million grant. Write the 750-word concept paper that: names the problem with national-scale data on Black maternal mortality; describes your solution and why it is distinctive, scalable, and financially viable; explains what a $100 million investment would accomplish over five years across ten high-burden Southern states; and addresses MacArthur's four criteria — importance, evidence, feasibility, and durability. Write for generalist MacArthur trustees using plain language and one compelling statistic per paragraph.","tags":["grant-writing","macarthur","concept-paper","maternal-health","scale"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-5","title":"USAID Award Budget Narrative","prompt":"You are the Finance Manager at an international development NGO implementing a food security program in northern Ethiopia under a USAID Food for Peace Development Food Security Activity award for $12 million over five years. Write the detailed budget narrative for Year 1 ($2.4 million) justifying these cost categories to the USAID Agreement Officer's Representative: Personnel (4 international staff and 22 national staff — justify salary levels against Hay Group market surveys and USAID allowable cost guidelines); Fringe Benefits (Ethiopia statutory rates for pension and health); Travel (international travel for the semi-annual USAID portfolio review in Addis Ababa and quarterly field monitoring visits by Denver HQ staff); and Indirect Costs (your negotiated indirect cost rate agreement of 22%). Each justification must reference the applicable 2 CFR 200 cost principle and demonstrate the cost is allowable, allocable, and reasonable.","tags":["grant-writing","USAID","budget-narrative","federal-compliance","2CFR200"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-6","title":"Robert Wood Johnson Foundation Health Equity Proposal","prompt":"You are the Research Director at a community health center network in rural Appalachian Ohio serving 14,000 patients annually across six Federally Qualified Health Centers. You are applying to the Robert Wood Johnson Foundation's Health Equity program for a $450,000 three-year grant to test a social needs screening and referral protocol using the PRAPARE tool integrated into your Epic EHR system. Write the full proposal narrative (maximum 2,000 words) with these sections: Background and Significance (connect your patient population's social determinants profile to RWJF's culture of health framework); Intervention Description (explain the PRAPARE workflow, warm handoff protocol to community health workers, and the FindHelp community resource database); Research Design (pre-post quasi-experimental design, primary outcome of reduction in ED utilization, IRB approval process); and Dissemination Plan (peer-reviewed journal publication and NACHC annual conference presentation). Use RWJF's preferred language around equity, assets, and lived experience.","tags":["grant-writing","RWJF","health-equity","FQHC","PRAPARE","appalachia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-7","title":"Government Contract Renewal Proposal","prompt":"You are the Program Director at a workforce development nonprofit in Los Angeles that has held a $1.2 million annual contract with the LA County Workforce Development Board for four years to operate a sector-based training program in healthcare support occupations (CNA, medical assistant, phlebotomy). Write the renewal proposal narrative for the next two-year contract period (maximum 2,500 words) covering: Performance Against Prior Contract Goals (actual numbers vs. contracted targets for enrollments, completions, credential attainment, job placements, and wage outcomes — be honest about one year where placement targets were missed and explain your corrective action); Program Model Description (employer-led curriculum design with Cedars-Sinai and Kaiser Permanente, paid training stipend model, and job retention coaching through 90 days post-placement); Work Plan and Milestones for the New Period; and Staff Qualifications. Match the compliance-oriented, data-heavy tone of a government contract renewal.","tags":["grant-writing","government-contract","workforce-development","renewal","healthcare-training"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-8","title":"Kresge Foundation Capacity-Building Grant","prompt":"You are the Executive Director of a 12-year-old immigrant rights legal services nonprofit in Phoenix with eight staff and a $900,000 annual budget that has never had a dedicated Development staff person. You are applying to the Kresge Foundation's Social Investment Practice for a $200,000 two-year organizational capacity grant to hire your first Director of Development and build out a donor database in Salesforce NPSP. Write the proposal narrative (maximum 1,800 words) covering: Organizational Self-Assessment (current fundraising weaknesses: 78% government funding concentration, no CRM, no major gifts program); Capacity-Building Plan (Year 1 and Year 2 actions — hire timeline, Salesforce implementation with a consultant, donor cultivation strategy targeting 25 major donors at $10,000+); Expected Outcomes (revenue mix at end of Year 2); and Long-term Sustainability (how the new Development Director pays for themselves within three years). Kresge reviewers respond to organizational candor and a concrete theory of change for the investment.","tags":["grant-writing","kresge","capacity-building","organizational-development","immigrant-rights"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-9","title":"Corporate Foundation STEM Education Grant","prompt":"You are the Partnership Manager at a youth STEM nonprofit in Atlanta that runs a summer coding and robotics camp for 400 middle schoolers annually, with 85% of participants being Black and Latino youth from Title I schools in Fulton County. You are applying to Google.org for a $500,000 grant to develop an AI literacy curriculum and train 60 middle school teachers across Atlanta Public Schools. Write the project proposal (maximum 1,200 words) in the Google.org format: Problem (quantify the gap in AI literacy education in Georgia middle schools using Georgia Department of Education data); Solution (curriculum design process, 40-hour teacher professional development model, student-facing project-based learning units); Impact (theory of change from teacher training to student AI fluency — measurable targets for the grant period); Team (curriculum design team qualifications and existing APS partnership); and Scale Plan (how this model could expand statewide with a follow-on investment).","tags":["grant-writing","corporate-foundation","STEM","AI-literacy","K12","atlanta"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-10","title":"Disaster Recovery Emergency Grant Request","prompt":"You are the Executive Director of a community food bank serving rural coastal North Carolina that was severely impacted by a Category 3 hurricane 11 days ago, destroying your refrigerated storage facility and displacing 40% of your regular client households. You need to submit an emergency grant request to the North Carolina Community Foundation's Disaster Recovery Fund for $175,000. Write the two-page emergency request letter that: opens with a specific factual account of the damage (date, scope, number of households currently unable to access food distribution); explains exactly what the $175,000 will cover (cold storage equipment replacement with three vendor quotes, temporary site lease, additional staff hours, transportation costs to reach displaced households); demonstrates your pre-disaster credibility (years of operation, annual pounds distributed, Feeding America network membership); and commits to a 60-day reporting timeline. Write with urgency and specificity, avoiding disaster-appeal clichés.","tags":["grant-writing","emergency-grant","disaster-recovery","food-bank","north-carolina"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-11","title":"Major Gift Ask Preparation Brief","prompt":"You are the Major Gifts Officer at a 45-year-old regional land trust in Vermont that has protected 180,000 acres of farmland and forest. You are preparing for a major gift conversation with a retired tech entrepreneur and her husband who have attended two farm tours, donated $5,000 annually for three years, and recently mentioned to a board member they are interested in legacy giving. Your goal is a $500,000 gift over five years to endow a farmland protection revolving loan fund. Write a complete pre-meeting preparation brief (two pages) including: a donor profile summary with giving history and interests; the specific project you will present and why it matches their values around local food systems and climate; your opening conversation arc from relationship-building to project introduction to the ask; three variations of the ask language calibrated to $300K, $500K, and $750K; two anticipated objections (estate planning concerns, geographic restrictions) with your responses; and your proposed follow-up actions within 48 hours of the meeting.","tags":["fundraising","major-gifts","ask-preparation","land-trust","donor-relations"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-12","title":"Year-End Direct Mail Appeal","prompt":"You are the Annual Fund Manager at a 200-bed residential treatment nonprofit in Minneapolis that provides long-term recovery housing for adults with substance use disorder, 70% of whom are justice-involved. Your year-end direct mail appeal targets 4,200 lapsed and current donors with an average gift of $85. Write the complete appeal package: a two-page letter (800 words maximum) from your Executive Director that opens with a specific composite resident story showing before/after transformation, connects the reader's past gift to a concrete program outcome, makes a specific ask tied to an operational cost ($1,200 funds one month of peer support coaching for one resident), and closes with a P.S. creating urgency around your December 31 deadline; a reply card with three suggested gift amounts ($75, $150, $300) and an open field; and a three-line outer envelope teaser. Do not use recovery clichés. Write for a donor who gives $85 and cares deeply but is not a treatment professional.","tags":["fundraising","annual-fund","direct-mail","year-end","substance-use"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-13","title":"Lapsed Donor Reactivation Email Sequence","prompt":"You are the Development Associate at a refugee resettlement agency in Columbus, Ohio that resettled 340 families last year. You have 680 donors who gave between 2019 and 2021 but have not given since. Write a three-email reactivation sequence spaced 10 days apart: Email 1 (subject line + 250-word body) — acknowledge the lapse without guilt, lead with a meaningful update on how your work has changed, and make a soft re-engagement ask; Email 2 (subject line + 200-word body) — share a specific family story (Ahmed, a Somali Bantu father of four who arrived in 2022 and now owns a catering business in Columbus) as proof of impact, with a specific ask of $50 to cover one month of English language classes for one adult learner; Email 3 (subject line + 150-word body) — final notice tone, offering an alternative engagement option (upcoming community dinner, social media follow) for donors who truly cannot give financially right now. Each email must have a unique, non-generic subject line that a lapsed donor would actually open.","tags":["fundraising","lapsed-donors","email-sequence","reactivation","refugee-resettlement"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-14","title":"Planned Giving Society Launch Plan","prompt":"You are the Development Director at a 60-year-old social services agency in Philadelphia with a $4 million annual budget and 1,800 active donors, roughly 200 of whom are over age 65 and have given for more than 10 consecutive years. Your Executive Director has tasked you with launching a legacy giving society (the Founders Circle) within six months. Write a detailed launch plan (three pages) covering: the case for establishing a legacy society now (aging donor base analysis, bequest revenue projections); the Founders Circle offer — what donors receive (recognition, insider communications, annual lunch with the ED); the outreach strategy for the top 30 prospects from your existing file, including a conversation guide a non-fundraising board member could use; marketing materials needed (one-page brochure copy, website landing page copy, sample bequest language for a donor's attorney); a 6-month implementation timeline with assigned responsibilities; and how to handle donors who want to make a bequest but are not ready to disclose the amount.","tags":["fundraising","planned-giving","legacy-society","major-gifts","philadelphia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-15","title":"Mid-Level Donor Stewardship Plan","prompt":"You are the Donor Relations Manager at a children's hospital foundation in Denver with a mid-level giving society (donors giving $1,000–$9,999 annually) of 340 members generating $620,000 per year. Retention in this segment dropped from 72% to 61% over two years. Write a 12-month stewardship plan to rebuild retention to at least 70%. The plan must include: a tiered touchpoint calendar by month (impact reports, event invitations, personal calls, digital updates) differentiated for new vs. renewing members; specific content for each touchpoint (the actual impact story format, the specific event you will host, the phone call script outline for board members making thank-you calls); a mid-level upgrade strategy targeting the top 40 members showing signals of readiness for a major gifts conversation; metrics you will track monthly (retention rate, upgrade rate, average gift size, response rate by touchpoint type); and a cost-per-retained-donor analysis showing the ROI of the stewardship investment. Do not suggest generic newsletter tactics.","tags":["fundraising","stewardship","mid-level-giving","donor-retention","hospital-foundation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-16","title":"Giving Tuesday Campaign with Board Matching Gift","prompt":"You are the Digital Fundraising Manager at a 10-year-old ocean conservation nonprofit in San Francisco with 12,000 email subscribers, 22,000 Instagram followers, and a Giving Tuesday average of $38,000 over the past three years. A board member has offered to match all gifts up to $25,000 on Giving Tuesday. Write the complete campaign plan covering: the campaign narrative and match framing (how to explain the match to maximize urgency without sounding formulaic); a day-of email cadence (three emails: 8am launch, midday update with matching progress bar language, 8pm final push — write subject lines and key messages for each); an Instagram and Facebook content plan for the week before and the day of (five posts with captions and creative directions); a text message sequence for your 3,400 SMS subscribers (two messages); and a staff and volunteer activation plan for personal social sharing. Include a realistic goal of $60,000 total including the match and explain the psychological framing behind each campaign element.","tags":["fundraising","giving-tuesday","matching-gift","digital-fundraising","ocean-conservation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-17","title":"Corporate Partnership Pitch for Fair Chance Hiring","prompt":"You are the Corporate Partnerships Manager at a workforce development nonprofit in Houston that places formerly incarcerated individuals into construction and skilled trades careers. Your graduates have a 94% job offer rate after a 16-week program. You are pitching a three-year, $750,000 partnership to the VP of CSR at a regional construction company with 800 employees that has publicly committed to fair chance hiring. Write the complete outline and talking points for a 20-minute pitch (eight slides): Slide 1 — the business problem (skilled trades labor shortage in Houston, quantified); Slide 2 — who your graduates are and why they are highly motivated workers; Slide 3 — program model and outcomes data; Slide 4 — the partnership offer (hiring pipeline access, joint PR, tax benefits, employee volunteer opportunities); Slide 5 — proposed investment and what it funds; Slide 6 — case study of an existing employer partner; Slide 7 — three-year partnership roadmap; Slide 8 — the ask and next steps. Include specific language for addressing concerns about insurance and background check policies.","tags":["fundraising","corporate-partnerships","workforce-development","fair-chance-hiring","houston"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-18","title":"Personalized Donor Impact Letter Template","prompt":"You are the Development Director at a CDFI in rural New Mexico that provides small business loans to Native American entrepreneurs on and near the Navajo Nation. You need to create a personalized impact report for donors who gave $500 or more last year — approximately 85 people. Write a template for a two-page personalized impact letter that: opens by addressing the donor by name and referencing their specific gift amount and date; translates their specific gift into a concrete fraction of a loan outcome (e.g., a $500 gift contributed to a $15,000 microloan that helped Maria Nez open a weaving studio in Gallup); presents three portfolio-level statistics (total loans deployed, jobs created or retained, percentage of borrowers who are women); shares a brief narrative profile of one loan recipient (with permission, first name and business type); explains how the CDFI model recycles capital so their gift has a multiplier effect; and closes with a specific ask for this year's renewal gift. The tone must feel like a letter from a colleague, not a form document.","tags":["fundraising","impact-reporting","CDFI","donor-stewardship","native-american"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-19","title":"Monthly Giving Upgrade Campaign","prompt":"You are the Retention Manager at a domestic violence services nonprofit in Baltimore with 1,100 active monthly donors giving an average of $22 per month. You want to run a 60-day campaign to upgrade 15% of monthly donors to a higher amount, targeting those who have given at the same level for more than 18 months with email open rates above 40%. Write the complete upgrade campaign: a segmented email sequence (three emails over 45 days — write complete subject lines and full body copy for each, maximum 200 words per email) that acknowledges their loyal monthly support, shows them what an additional $8/month would fund (three additional nights of emergency shelter per year for one survivor), and makes the upgrade feel easy and impactful; a follow-up SMS for non-openers after email 2; the landing page copy for a one-click upgrade page; and talking points for board members making personal phone calls to the top 50 highest-potential upgraders. Include the framing psychology behind why you are asking for a small dollar increase rather than a percentage increase.","tags":["fundraising","monthly-giving","upgrade-campaign","domestic-violence","donor-retention"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-20","title":"Annual Gala Post-Event ROI Analysis","prompt":"You are the Events Manager at a performing arts nonprofit in Boston that just completed its annual gala, which raised $380,000 gross from 280 attendees with $195,000 in net revenue after $185,000 in event costs. Net margin dropped from 56% to 51% because catering costs increased 28%. Write a complete post-event analysis report (two pages) for your Executive Director and Board Treasurer covering: financial performance with a year-over-year comparison table (revenue by source: ticket sales, sponsorships, live auction, fund-a-need, table sales); cost analysis identifying which cost categories grew most and why; donor acquisition and retention metrics (new donors, lapsed donors returning, average gift size by donor segment); qualitative assessment of what worked and what did not; and three specific recommendations for next year with projected financial impact — specifically: restructuring the live auction from 10 items to 5 high-value items, renegotiating the catering contract, and adding a new $500-per-person Patron Table tier. Write in a tone appropriate for a board finance committee.","tags":["fundraising","events","gala","ROI-analysis","performing-arts"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-21","title":"Theory of Change for a Re-entry Program","prompt":"You are the Program Design Director at a 20-staff criminal justice reform nonprofit in New Orleans launching an 18-month re-entry program for people returning from Louisiana state prisons with fewer than 12 months remaining on parole supervision. The program combines peer mentorship, workforce training in construction trades, and civic engagement through participatory action research. Write a complete Theory of Change narrative (maximum 1,500 words) that: defines the problem with Louisiana-specific recidivism and employment barrier data; articulates your long-term outcome (reduced recidivism and economic self-sufficiency for 150 participants over three years); maps the causal chain from inputs (staff, peer mentors, employer partners) through activities (weekly peer groups, 12-week trades pre-apprenticeship, monthly civic action projects) to outputs (completions, credentials, job placements) to short-term outcomes (stable housing, employment at 90 days) to long-term outcomes (12-month recidivism reduction, civic leadership); names the key assumptions your theory rests on; and identifies external conditions that must hold. Format as a narrative with an accompanying visual logic model described in text.","tags":["program-design","theory-of-change","re-entry","criminal-justice","new-orleans"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
  {"id":"ngo-22","title":"Logic Model for Maternal Mental Health Program","prompt":"You are the Program Officer at a community health nonprofit in rural Georgia serving the Black Belt region. You are designing a program to reduce postpartum depression among Black mothers in five counties with no psychiatrist within 60 miles. The program will train OB/GYN nurses in the Edinburgh Postnatal Depression Scale screening protocol, establish a telepsychiatry referral pathway with Emory Healthcare, and provide 10 weeks of peer support groups facilitated by trained community health workers. Create a detailed logic model in standard five-column format (Inputs, Activities, Outputs, Short-term Outcomes, Long-term Outcomes) with at least four rows per column. After the table, write a one-page narrative explaining the three most critical assumptions embedded in the logic model, the two biggest risks to achieving the outcome pathway, and how you will know at 12 months whether the program is on track. Be specific about the measurement tool for each short-term outcome.","tags":["program-design","logic-model","maternal-mental-health","rural-health","georgia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-23","title":"Human-Centered Program Design Workshop Agenda","prompt":"You are the Director of Programs at a 35-person immigrant services nonprofit in Minneapolis asked by the Minnesota Department of Human Services to design and pilot a financial capability program for recently arrived Karen (Burmese) refugees with extremely limited banking history. You have $180,000 and six months. Design a complete two-day program design workshop agenda for your internal team of six staff plus four Karen community co-designers. The agenda must include: Day 1 (8 hours) — community asset mapping using appreciative inquiry, lived experience panel with four Karen community members, review of the FDIC Bank On financial capability evidence base, and user journey mapping; Day 2 (8 hours) — program model prototyping using a human-centered design sprint format, development of three candidate program models, evaluation criteria weighting exercise, and selection of a pilot model with community co-designer vote. For each session, specify the facilitation method, materials needed, time allocation, and what output will be produced.","tags":["program-design","workshop-facilitation","financial-capability","refugees","human-centered-design"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-24","title":"EU-Funded Food Security MEAL Framework","prompt":"You are the MEAL Coordinator at an international NGO implementing a three-year, $3.5 million food security and resilient livelihoods program in rural Zimbabwe (Masvingo Province) funded by the European Union. The program serves 8,000 smallholder farming households through seed and input vouchers, climate-smart agriculture training, and village savings and loan association (VSLA) formation. Design a complete MEAL framework document (maximum four pages) including: a performance monitoring matrix with indicators at output, outcome, and goal levels aligned to the EU Results Framework (baseline value, end-of-project target, data source, collection frequency, and responsible party for each indicator); a learning agenda with three priority learning questions; a data collection calendar showing when household surveys, FGDs, post-distribution monitoring, and VSLA monitoring will occur by quarter; a description of your adaptive management process — specifically how you will use mid-year learning reviews to make program adjustments; and a beneficiary feedback mechanism describing how you will collect, analyze, and act on complaints from all 8,000 households.","tags":["program-design","MEAL","food-security","zimbabwe","EU-funding","livelihoods"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-25","title":"Evidence Review for Youth Mental Health Intervention Selection","prompt":"You are the Director of Learning and Innovation at a mid-sized youth development organization in Los Angeles serving 2,400 teenagers annually in after-school programs at 18 high schools. Your board approved funding to add a mental health component and you need to select an evidence-based intervention to pilot in three schools next year. Write a structured evidence review memo (maximum 2,000 words) evaluating three candidate interventions: the Penn Resiliency Program, Cognitive Behavioral Intervention for Trauma in Schools (CBITS), and Sources of Strength. For each intervention, address: the evidence base (RCT or quasi-experimental studies, effect sizes, populations studied); implementation requirements (staff training hours, supervision needs, session structure, materials costs); fit with your population (urban, predominantly Latino and Black adolescents, many with trauma histories and housing instability); and scalability from 3 to 18 schools over three years. Conclude with a recommendation and the additional information you would need from each developer before a final decision. Write for a board program committee, not an academic audience.","tags":["program-design","evidence-based-practice","youth-mental-health","intervention-selection","los-angeles"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-26","title":"Community Needs Assessment Design","prompt":"You are the Program Director at a neighborhood-based CDC in Cleveland's Glenville neighborhood, which is 95% Black, has a median household income of $28,000, and has experienced significant population decline over 30 years. Your CDC has $60,000 from the Cleveland Foundation to conduct a comprehensive community needs and assets assessment. Design the full assessment methodology (maximum 2,500 words) covering: secondary data sources to analyze (American Community Survey, Cleveland Metropolitan School District data, Cuyahoga County health data, HMDA mortgage data); primary data collection — a 40-question household survey instrument design (describe sections and key questions), four neighborhood focus groups with specific recruitment strategies for hard-to-reach populations (seniors, undocumented residents, youth aged 14–19), and eight key informant interviews (specify which roles and why); your community asset mapping process using participatory GIS; data analysis approach; and your community report-back plan (how will you share findings with residents before publishing). Name a specific potential bias at each stage and how you will mitigate it.","tags":["program-design","needs-assessment","community-development","cleveland","participatory-research"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-27","title":"Scaling Strategy for a Proven Education Program","prompt":"You are the VP of Programs at a charter school support organization in Oakland that developed an intensive principal coaching model producing statistically significant reading proficiency gains at seven Bay Area schools over four years, with a rigorous RAND Corporation evaluation. The W.K. Kellogg Foundation has expressed interest in funding a $2 million scale-up to 30 schools in five California counties over three years. Write a scaling strategy memo (maximum 2,000 words) that: defines the core active ingredients of the program model (what must maintain fidelity) and what is adaptable to local context; assesses your current organizational capacity gaps for scaling (staff, training infrastructure, data systems, financial management); proposes a tiered scaling approach (direct delivery vs. train-the-trainer vs. licensing to partner organizations) and recommends one with justification; addresses the quality vs. quantity tension and how you will monitor program fidelity at scale; includes a financial sustainability model showing revenue per school, cost per school, and break-even point; and identifies the three biggest risks to successful scale with mitigation strategies.","tags":["program-design","scaling","principal-coaching","oakland","kellogg","program-fidelity"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-28","title":"Tribally-Led Community Health Worker Program Design","prompt":"You are the Program Officer at a Pacific Northwest tribal health department serving the Quinault Indian Nation in Washington State. You have received a CDC Community Health Worker training grant and must design the training curriculum in a way that is tribally led, culturally grounded, and does not replicate extractive research practices that have historically harmed Indigenous communities. Write a program design approach document (maximum 1,800 words) that: describes your tribal data sovereignty principles and how they will govern data collection and ownership; outlines the community co-design process — which tribal members, elders, and departments will be involved in what decision-making roles; explains how you will integrate Quinault cultural values and traditional healing knowledge alongside CHW evidence-based competencies from the national C3 Project standards; addresses the tension between CDC's standardized training requirements and the need for tribal cultural adaptation; proposes a community advisory structure with real authority; and defines what success looks like from a tribal self-determination perspective, not just a CDC output framework.","tags":["program-design","indigenous-communities","tribal-health","community-health-workers","data-sovereignty"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-29","title":"Program Pivot Decision Framework","prompt":"You are the Executive Director of a workforce development nonprofit in Detroit that has run a certified nursing assistant (CNA) training program for eight years, graduating 120 people per year. Your latest cohort data shows 60-day job retention dropped from 78% to 52% over three years, primarily because hospital systems switched to new scheduling software requiring tech skills your graduates lack. New data shows medical coding and health information technician roles pay 40% more than CNA roles and have lower turnover. Write a program pivot decision framework memo (maximum 1,500 words) for your board that: defines the problem with three years of your own program data; presents three options (update the CNA curriculum, add a medical coding track alongside CNA, sunset CNA and launch medical coding); evaluates each option against four criteria (mission alignment, financial feasibility, community demand from focus group data, competitive landscape in Detroit); makes a clear recommendation with rationale; identifies the stakeholders most affected (CNA instructor staff, hospital partners, community referral agencies) and your communication plan for each; and proposes a 90-day decision validation process before a full board vote.","tags":["program-design","program-pivot","workforce-development","detroit","decision-making"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-30","title":"Gender-Responsive Program Redesign in Bangladesh","prompt":"You are the Gender Equality Advisor at an international NGO implementing an agricultural livelihoods program in rural Bangladesh reaching 12,000 smallholder farmers in Rajshahi Division. A mid-term evaluation found that women — 48% of enrolled participants — are receiving only 31% of productive assets distributed (seeds, fertilizer vouchers, training) because male household heads are intercepting program benefits. Write a program redesign recommendation memo (maximum 2,000 words) for the Country Director that: documents the gender gap with mid-term data; analyzes root causes (household dynamics, program agent behavior, enrollment process design, community norms); proposes five specific design changes to the delivery model (e.g., women-only distribution events, mobile money transfers directly to women participants, female field agent hiring targets, gender-sensitive monitoring indicators, separate women's farmer groups); estimates the cost of each design change; and addresses the risk that more aggressive gender-targeting could provoke household-level conflict and harm women participants — and what your safeguarding response should be.","tags":["program-design","gender-equality","gender-responsive","bangladesh","livelihoods","safeguarding"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-31","title":"Impact Evaluation Design — Permanent Supportive Housing","prompt":"You are the Director of Research and Evaluation at a 50-staff homeless services nonprofit in Portland, Oregon operating a Housing First permanent supportive housing program with 340 residents across six apartment buildings. The Robert Wood Johnson Foundation has offered to fund an independent impact evaluation. Write a complete evaluation design brief (maximum 2,500 words) that: states the primary evaluation question (does permanent supportive housing with wraparound services reduce emergency room utilization and psychiatric hospitalization among chronically homeless adults with serious mental illness compared to usual care?); reviews the existing evidence base including the At Home/Chez Soi study and Pathways to Housing RCT; proposes a quasi-experimental difference-in-differences design using Medicaid claims data and a waitlist comparison group; describes your primary and secondary outcomes and how you will measure them; addresses the ethical tension of using a waitlist as a comparison group; outlines your data sharing agreement requirements with Oregon Health Authority; identifies the three biggest threats to internal validity and how you will address each; and proposes a realistic evaluation budget and timeline.","tags":["monitoring-evaluation","impact-evaluation","housing-first","portland","quasi-experimental","RWJF"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-32","title":"Annual Impact Report Data Storytelling Section","prompt":"You are the Communications and Evaluation Manager at a digital inclusion nonprofit in Atlanta that refurbished and distributed 4,200 laptops to low-income households last year, trained 1,800 adults in digital literacy through 24 community partner sites, and helped 340 seniors access telehealth services for the first time. Write the data section of your annual impact report (maximum 1,200 words plus descriptions of four data visualizations) for a donor audience. Write the narrative text and describe each visualization in detail: use a compelling headline statistic to open; translate raw numbers into human-scale equivalents; show year-over-year growth with honest context about what drove it; include one data point where you fell short of your goal and explain what you learned; describe four specific charts or infographics (specify chart type, data displayed, and design direction for each); and close with a forward-looking statement connecting this year's data to your 2027 goal. Avoid impact inflation and data cherry-picking — write the kind of honest, specific report that sophisticated donors trust.","tags":["monitoring-evaluation","impact-reporting","data-storytelling","digital-inclusion","atlanta"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-33","title":"Digital Data Collection System for Low-Connectivity Field Programs","prompt":"You are the MEAL Manager at an NGO implementing a nutrition and WASH program in South Sudan serving 45,000 beneficiaries across 12 hard-to-reach counties. Your program has been using paper-based data collection, resulting in a 6–8 week reporting lag. Your new USAID award requires real-time dashboard reporting. Design a complete digital data collection system (maximum 2,000 words) specifying: your choice of mobile data collection platform (compare KoboToolbox vs. ODK vs. CommCare for your specific context — low connectivity, 35 field staff with varying tech literacy, server hosting in a conflict-affected country) and your selection rationale; the server and connectivity architecture (offline data collection with scheduled sync, satellite internet at field offices); your data management workflow from enumerator to field supervisor to HQ analyst; the data quality assurance steps at each level (range checks, outlier flags, supervisor back-checks, audit trails); your Power BI dashboard design showing the five key indicators program management needs daily; staff training requirements; and your data security and beneficiary protection protocol including encryption and access controls.","tags":["monitoring-evaluation","data-collection","KoboToolbox","south-sudan","USAID","data-systems"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-34","title":"Mid-Term Evaluation Terms of Reference — Girls Education","prompt":"You are the Program Director at an international NGO implementing a four-year, $6 million girls' education program in rural Pakistan (Sindh Province) funded by FCDO, now in its second year. You are commissioning an independent mid-term evaluation. Write the complete Terms of Reference (maximum 2,500 words) that an external evaluation firm would receive when bidding on this contract, including: program background and context (max 300 words); evaluation purpose and intended use; five primary evaluation questions spanning OECD DAC relevance, effectiveness, efficiency, and emerging sustainability criteria, plus two learning questions specific to girls' safety in education; evaluation methodology requirements (mixed-methods design: household survey, FGDs with girls, boys, parents, and teachers, key informant interviews with government education officials, document review — specify minimum sample sizes); ethical requirements for working with minor girls in a conservative context (safeguarding, consent, girl-centered data collection methods); deliverables and timeline; evaluator qualification requirements; and budget ceiling of $85,000.","tags":["monitoring-evaluation","terms-of-reference","mid-term-evaluation","girls-education","pakistan","FCDO"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-35","title":"USAID CLA Plan for Democracy and Governance Program","prompt":"You are the Senior MEAL Advisor at a US-based international development organization implementing a five-year Democracy, Rights, and Governance program in Kenya funded by USAID at $8 million. The program works with civil society organizations to strengthen civic participation and election integrity. Write a Collaborating, Learning, and Adapting (CLA) plan (maximum 2,000 words) that: defines your three priority learning questions for Year 1 and explains why they are the most critical uncertainties to resolve for program success; describes your collaborative learning structure — who participates in quarterly learning reviews (USAID COR, implementing partner CSOs, government counterparts), how the sessions are structured, and what decisions they are authorized to make; explains your adaptive management decision-making protocol (what types of changes require USAID approval vs. can be made at program level, and what documentation is required); describes how you will surface and act on negative feedback or evidence that an activity is not working; and outlines your knowledge management approach for capturing and sharing learning with the broader DRG community of practice.","tags":["monitoring-evaluation","learning-agenda","adaptive-management","CLA","Kenya","USAID"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-36","title":"Post-Distribution Monitoring Survey for Cash Assistance","prompt":"You are the Accountability to Affected Populations Officer at a humanitarian NGO distributing emergency cash assistance ($150 per household per month for three months) to 12,000 conflict-affected households in northern Mozambique (Cabo Delgado Province). Design a complete Post-Distribution Monitoring survey to be conducted with a random sample of 400 households 30 days after the first distribution. The design document (maximum 1,800 words) must include: sampling methodology (stratified random sample by distribution site and household head gender, with replacement procedure); the complete survey instrument structure with sections on receipt verification, cash expenditure tracking using a 14-item recall list, market functionality assessment, protection concerns during collection, feedback on the registration process, and suggestions for improvement; specific probing questions to detect aid diversion or coercive practices; data entry and analysis plan (same-day KoboToolbox entry, weekly summary tables, flag triggers for follow-up); and your escalation protocol when the PDM reveals protection concerns. Include three survey questions verbatim as examples of your quality standards.","tags":["monitoring-evaluation","post-distribution-monitoring","humanitarian","cash-assistance","mozambique"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-37","title":"Organizational Learning System Design","prompt":"You are the Knowledge Management Director at a 120-staff international NGO headquartered in Geneva with programs in 14 countries. Your CEO has asked you to design an organizational learning system that moves beyond after-action reviews nobody reads. Write a complete organizational learning system design document (maximum 2,500 words) that: diagnoses the five most common failure modes of NGO learning systems (siloed data, no protected time, findings not linked to decisions, staff turnover erasing institutional memory, donors not valuing learning investments); proposes a three-tier learning architecture: Tier 1 (project-level real-time learning using structured reflection protocols), Tier 2 (program-level quarterly sense-making with cross-country comparison), Tier 3 (organizational-level annual strategic learning retreats); specifies roles and responsibilities at each tier including a new part-time Country Learning Champion role; describes your knowledge management technology recommendation (Microsoft SharePoint with structured tagging taxonomy — explain why over custom systems); proposes a learning culture measurement approach using a validated organizational learning survey; and estimates the total investment and makes the business case in terms of program quality and donor relations.","tags":["monitoring-evaluation","organizational-learning","knowledge-management","international-NGO","learning-systems"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-38","title":"Beneficiary Feedback Mechanism for Rohingya Refugee Camp","prompt":"You are the Accountability Officer at a refugee camp management NGO operating in a camp of 65,000 Rohingya refugees in Cox's Bazar, Bangladesh. The IASC Core Humanitarian Standard requires a functioning community feedback mechanism. Write a complete feedback mechanism design document (maximum 2,000 words) covering: the full range of feedback channels (suggestion boxes with weekly collection, community liaison network of 24 elected representatives, two hotlines staffed during distribution hours, women-only feedback sessions twice monthly in private spaces); the intake, categorization, and referral workflow from receipt to resolution — include a process flowchart described in text with time standards at each step (acknowledgment within 24 hours, resolution within 10 days for non-sensitive complaints); the separate secure pathway for protection-related complaints including SEA that goes directly to the NGO's PSEA focal point and the camp-level PSEA network coordinator; how you will close the feedback loop with complainants who cannot read and do not have phones; and your monthly reporting structure showing aggregated feedback trends. Identify three ways the mechanism could fail and how you will prevent each.","tags":["monitoring-evaluation","accountability","beneficiary-feedback","rohingya","humanitarian","PSEA"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-39","title":"Social Return on Investment Analysis for Supported Employment","prompt":"You are the Impact Manager at a supported employment nonprofit in Toronto that places people with developmental disabilities into competitive, integrated employment at market wages. Last year, you placed 68 people into jobs averaging $18.50/hour with 74% 12-month retention. Your board wants a Social Return on Investment analysis for funder conversations and policy advocacy. Write a complete SROI analysis methodology document (maximum 2,000 words) that: identifies all stakeholder groups and their specific inputs and outcomes (employees placed, their families, employers, Ontario government, ODSP income support system); defines the financial proxies you will use to monetize outcomes for each stakeholder group — be specific about data sources (Statistics Canada wage data, OHIP cost data, Ontario Works benefit rates, employer productivity research); explains your counterfactual assumption referencing the Ontario employment rate for people with developmental disabilities without supported employment; calculates a draft SROI ratio range with sensitivity analysis showing how the ratio changes with conservative vs. optimistic assumptions for the two most uncertain variables; and addresses the most common critiques of SROI methodology and explains how your analysis mitigates them.","tags":["monitoring-evaluation","SROI","social-return","developmental-disabilities","employment","toronto"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-40","title":"Multi-Funder Grant Compliance Monitoring System","prompt":"You are the Grants Compliance Manager at a US-based NGO managing seven active federal grants (three USAID cooperative agreements, two HHS grants, one Department of Labor grant, one EPA environmental justice grant) totaling $18 million annually, plus 12 private foundation grants. Write a comprehensive grant compliance monitoring system (maximum 2,500 words) that: creates a grant compliance calendar tool (describe the structure — a master spreadsheet with columns for each grant, rows for monthly compliance checkpoints) covering reporting deadlines, financial audits, prior approval requirements, and key personnel change notification requirements; specifies the compliance check routine for federal grants — monthly financial reconciliation against the SF-425, quarterly programmatic progress against work plan milestones, and annual single audit preparation; creates a prior approval tracker for actions requiring advance USAID or HHS approval (budget modifications over 10%, change in key personnel, no-cost extensions, equipment purchases over $5,000); describes the internal escalation protocol when a compliance issue is discovered; and proposes a grant close-out checklist for each grant type. Include specific references to applicable sections of 2 CFR 200 and USAID Standard Provisions.","tags":["monitoring-evaluation","grant-compliance","federal-grants","USAID","2CFR200"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-41","title":"Policy Brief on Medicaid Housing for State Legislators","prompt":"You are the Policy Director at a statewide health equity advocacy organization in Ohio working for three years to persuade the Ohio General Assembly to approve a Medicaid Section 1115 waiver to cover 12 months of transitional housing for people with serious mental illness being discharged from state psychiatric hospitals. Write a two-page policy brief (maximum 900 words in the body, plus a one-page executive summary) for members of the Ohio Senate Health Committee. Include: a problem statement with Ohio-specific data on psychiatric hospital readmissions, ED utilization by people with SMI, and housing instability costs to Medicaid; the proposed solution (clear description of what the 1115 waiver would allow, what it would cover, who would be eligible); the evidence base (cite Oregon's 1115 waiver results and Medicaid housing demonstration projects in New York and California); a realistic fiscal analysis showing the waiver cost and projected offset from reduced inpatient and ED spending with conservative assumptions; responses to the three most likely legislative objections; and a clear ask. Write in plain language accessible to a legislator with no health policy background.","tags":["communications","advocacy","policy-brief","medicaid","housing","ohio","mental-health"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
  {"id":"ngo-42","title":"90-Day State Legislative Advocacy Campaign Plan","prompt":"You are the Advocacy Director at a statewide tenants rights organization in California with 8,000 members across 14 counties. You are running a 90-day campaign to pass AB 2370, extending AB 1482's anti-rent-gouging protections to cover single-family homes currently exempt. Write a complete 90-day campaign plan covering: your theory of change for the legislative campaign (what needs to happen in the State Assembly and Senate for the bill to pass, who are the key swing votes, what will move them); your base mobilization strategy (how you will turn 8,000 members into active participants — phone banking protocol, text banking program using Hustle, in-district meeting strategy targeting 12 priority swing districts); your media strategy (earned media targets, op-ed placement plan, social media content calendar for weeks 1–4 with specific platform strategies for Twitter/X, Instagram, and TikTok); your coalition management plan (which organizations are co-sponsoring, what each will contribute, how you will coordinate without ceding message control); and your win/lose/compromise scenario planning — what is your BATNA if the bill stalls in committee?","tags":["communications","advocacy","campaign-planning","tenant-rights","california","grassroots"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-43","title":"48-Hour Crisis Communications Response Plan","prompt":"You are the Communications Director at a national child welfare advocacy nonprofit in Washington D.C. A prominent newspaper has just published an investigative piece alleging that your board chair personally directed your policy team to soften your position on a controversial child removal reform bill after receiving a large gift from a foundation with ties to the child welfare industry. The story is factually incorrect — your position change was driven by member survey data, not donor pressure — but the article is widely shared on social media within hours. Write a complete 48-hour crisis communications response plan: Hours 1–4 (internal assessment and response team activation — who is in the room, what decisions get made, and the immediate holding statement for media inquiries); Hours 4–12 (prepare and release a full organizational statement — write the complete 400-word statement that directly refutes the specific allegation with documentation and does not attack the reporter); Hours 12–24 (stakeholder outreach — write the email to your top 50 donors, the message to your board, and talking points for program staff); Hours 24–48 (proactive media outreach strategy, decision on requesting a correction, social media response protocol). Include a section on what NOT to do in the first 48 hours.","tags":["communications","crisis-communications","reputation-management","nonprofit","media-response"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-44","title":"Earned Media Strategy for Research Report Launch","prompt":"You are the Communications Manager at a child poverty research and advocacy organization in New York City releasing a major report on the two-year impact of the expanded Child Tax Credit that ran July–December 2021. Your data shows child poverty in New York State rose from 8.3% to 13.7% in the 12 months following the expiration, with the sharpest increases in Black and Latino families in the Bronx, East New York, and Brownsville. You are releasing the report on a Tuesday in late October. Write a complete earned media strategy covering: your media targeting strategy (which beat reporters at the New York Times, New York Daily News, Gothamist, City Limits, Univision New York, Politico, and The Atlantic); your embargo strategy (pitch under embargo to three top-tier reporters two days before release); the complete 500-word press release (headline, dateline, lead paragraph with top finding, two data points in the body, two quotes from different voices, and boilerplate); and your backup plan if the report does not get pickup on launch day (social media amplification, follow-up pitch angles, op-ed placement strategy).","tags":["communications","earned-media","research-report","child-poverty","new-york","media-strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-45","title":"Four-Week Digital Advocacy Campaign for Flint Water Funding","prompt":"You are the Digital Organizer at a clean water advocacy nonprofit in Flint, Michigan fighting for full lead pipe replacement and long-term water quality monitoring. Seven years after the Flint water crisis, 40% of lead service lines have still not been replaced. You are launching a digital campaign targeting the Michigan state legislature during the state budget appropriations process with a specific ask of $120 million for full pipe replacement completion. Design a four-week digital content calendar for Instagram, Facebook, and Twitter/X: Week 1 — establish the current crisis with data and a first-person video testimony from a Flint resident (describe content format and key messages); Week 2 — explain the budget ask in simple shareable terms and introduce a legislator accountability tracker; Week 3 — escalation week targeting five specific swing legislators by name, constituent call scripts, and a legislative office visit day rollout; Week 4 — momentum and win framing with a path forward message. For each week, specify three posts per platform with caption copy, visual direction, hashtag strategy, and engagement tactic. Write the actual caption text for two posts per week.","tags":["communications","digital-advocacy","clean-water","flint","michigan","content-calendar"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-46","title":"Op-Ed Drafting Guide for a Nonprofit Executive Director","prompt":"You are the Communications Director at a statewide early childhood advocacy coalition in Georgia. Your Executive Director — a brilliant program expert who has never written a public op-ed — needs to submit a 700-word op-ed to the Atlanta Journal-Constitution within 10 days responding to a state budget proposal that would cut Pre-K funding by 23%, removing 14,000 Georgia children from Pre-K seats in the year before kindergarten. Write a complete op-ed drafting guide for her (not the op-ed itself, but the writing guide with complete structure and sample sentences she can use). The guide should: explain the AJC op-ed format requirements and house style; provide a six-paragraph structure with the purpose of each paragraph and a sample opening sentence; explain how to open with a personal story hook before pivoting to policy — suggest two story options from program alumni she could use; specify the three data points she must include with source attribution; draft two possible closing calls to action; list five op-ed killers to avoid (jargon, defensive tone, too many numbers, no clear ask, passive voice); and then write the first two paragraphs in full as a model.","tags":["communications","op-ed","advocacy","early-childhood","georgia","writing-guide"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-47","title":"Annual Report Executive Director Message","prompt":"You are the Executive Director of a 25-year-old HIV/AIDS services organization in San Francisco that served 3,200 clients in the past fiscal year through case management, housing assistance, and peer health education. This was a year of significant transition: you launched a strategic plan, hired a new Chief Program Officer, navigated a major funding cut from the San Francisco Department of Public Health, and ended the year with a $180,000 surplus due to strong individual donor support. Write the Executive Director's Message for your annual report (maximum 750 words) that: opens with honest reflection on the challenges of the year, not a triumphant declaration; acknowledges the DPH funding cut directly and explains what it meant for clients and how your team responded; celebrates three specific accomplishments with real names and outcomes (a staff hire, a program milestone, a policy win); introduces the strategic plan in terms of what it means for clients in the next three years; and closes with a specific thank-you that names contributions beyond dollars that made the year possible. Write in a warm, honest first-person voice that sounds like a human being, not a nonprofit press release.","tags":["communications","annual-report","executive-director-message","HIV-AIDS","san-francisco"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-48","title":"Federal Rulemaking Public Comment on Housing Work Requirements","prompt":"You are the Policy Director at a national housing advocacy coalition with 140 member organizations across 38 states. The Department of Housing and Urban Development has proposed a rule change allowing public housing authorities to impose new work requirements on residents, affecting an estimated 280,000 households. Your coalition has 45 days to submit formal public comments. Write: a 200-word public statement from your coalition for immediate release, signed by all 140 members, that clearly opposes the rule and gives three specific reasons; a 1,500-word formal public comment to HUD (identify the rule by its Federal Register citation, state your organization's standing to comment, provide substantive policy analysis of why work requirements are contrary to the statutory purpose of public housing, cite specific research evidence including the Urban Institute's Administrative Burden research, and identify the specific populations who would be most harmed); and talking points for coalition members contacting their representatives in Congress — write four talking points in plain language for a constituent phone call to a congressional office.","tags":["communications","advocacy","coalition-statement","federal-rulemaking","public-housing","HUD"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-49","title":"Ethical Storytelling and Imagery Policy","prompt":"You are the Communications Director at a large international development NGO distributing 12 million print and digital communications per year featuring stories and images of people in communities you serve in sub-Saharan Africa, South Asia, and Latin America. A staff member recently flagged that one fundraising campaign used an image of a malnourished child without clear parental consent documentation, and another campaign featured a domestic violence survivor story with enough identifying details that a program country colleague recognized the woman. Write a comprehensive Ethical Storytelling and Imagery Policy (maximum 2,500 words) that: establishes core ethical principles (dignity, consent, accuracy, agency, do no harm); defines specific requirements for photo and video consent (written vs. oral consent protocols, different standards for emergency contexts, requirements for minors, the consent withdrawal process); sets standards for written storytelling (what identifying details are prohibited even with consent, what protective measures are required for survivors of violence or stigmatized health conditions, how to handle composite stories); describes the review and approval process for all content featuring beneficiaries before publication; and specifies consequences for policy violations. Reference the Images of Dignity code and CONCORD's Ethical Storytelling guidelines.","tags":["communications","storytelling-ethics","imagery-policy","consent","dignity","international-NGO"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
  {"id":"ngo-50","title":"Capitol Advocacy Day Preparation Toolkit","prompt":"You are the Advocacy Coordinator at a statewide disability rights organization in Wisconsin preparing for your annual Advocacy Day at the State Capitol, where 85 self-advocates with physical, intellectual, and developmental disabilities and their supporters will meet with 40 state legislative offices to advocate for increased Medicaid waiver funding for home and community-based services. Write the complete Advocacy Day preparation toolkit (maximum 2,500 words) that includes: the one-page leave-behind for legislators (write the actual text — a clear ask in dollar terms, two compelling data points on the HCBS waitlist, and a brief constituent story a self-advocate will tell in person); a two-page meeting preparation guide for self-advocates covering how a legislative meeting is structured, how to deliver a personal story in 90 seconds, and what to do when the legislator pushes back; an accessibility planning checklist for the Capitol visit covering physical accessibility, communication accessibility (AAC devices, interpreters), sensory considerations, rest break logistics, and emergency protocols; a post-meeting debrief form; and a day-of coordinator communication protocol.","tags":["communications","advocacy","lobbying-day","disability-rights","wisconsin","self-advocacy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-51","title":"Board Recruitment Matrix and Candidate Pipeline","prompt":"You are the Board Chair of a 12-year-old environmental education nonprofit in Portland, Oregon with a 9-member board that is predominantly white and predominantly from the nonprofit and academic sectors. Your strategic plan calls for expanding to serve communities of color in East Portland, and your board composition does not reflect those communities. You have 4 board seats to fill in the next 12 months. Write a comprehensive board recruitment strategy (maximum 2,000 words) that: creates a board skills and representation matrix showing your current board composition (skills, demographics, sectors, geography) and the gaps you are explicitly trying to fill (financial expertise, legal, community connections in East Portland, lived experience with environmental health issues, bilingual Spanish); defines the specific profile for each of the four open seats; describes your sourcing strategy for candidates who would not typically be on a nonprofit board radar (community associations, workplace giving programs, labor unions, faith communities); drafts the outreach message and meeting invitation for candidates who have no prior nonprofit board experience; describes your board orientation process that supports new board members from non-traditional backgrounds to be effective quickly; and addresses the structural changes your board needs to make to retain diverse members (meeting times, compensation for lost wages, translation support, childcare).","tags":["board-development","governance","recruitment","diversity","environmental-education","portland"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"ngo-52","title":"Board Fiduciary Training Curriculum","prompt":"You are the incoming Executive Director of a 40-year-old social services nonprofit in Baltimore with an $8 million annual budget whose board has not received structured fiduciary training in at least five years. Three recent incidents have exposed gaps: a board member disclosed confidential executive session information, a committee approved a vendor contract without proper conflict of interest disclosure, and three board members did not know your organization had a reserve fund policy. Design a four-session board fiduciary training curriculum (approximately 90 minutes per session) that can be delivered over two board meetings and two special sessions. For each session, specify: learning objectives (what board members will be able to do afterward); agenda with timing; the specific content to be covered (for Session 1: legal duties of care, loyalty, and obedience with case studies relevant to a social services nonprofit; for Session 2: financial oversight — reading the 990, understanding reserves, the audit process; for Session 3: conflict of interest policy and confidentiality in practice; for Session 4: board-ED relationship boundaries and effective governance practices); discussion questions; and a one-page reference card board members can keep. Specify which sessions should include your auditor, legal counsel, or insurance broker as a guest presenter.","tags":["board-development","governance","fiduciary","financial-oversight","training","baltimore"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-53","title":"Board Meeting Redesign for Strategic Engagement","prompt":"You are the Executive Director of a 20-staff immigration legal services nonprofit in Phoenix whose board meetings have become primarily operational reports and rubber-stamp approvals, leaving board members disengaged. Your last board retreat revealed that members want to spend more time on strategy and less time hearing staff updates they could read in advance. Design a completely redesigned board meeting structure for your nine-member board that meets six times per year (two hours per meeting). Write the redesign document (maximum 1,500 words) specifying: a new consent agenda process that moves all routine approvals and informational reports out of meeting time (describe what goes on the consent agenda and how it will be distributed and approved); a template for the 90 minutes of substantive meeting time (20 minutes for financial dashboard review using a one-page visual dashboard you will describe in detail, 60 minutes for one strategic discussion topic per meeting, 10 minutes for executive session check-in); the six strategic discussion topics you will schedule for the year tied to your organizational calendar; how you will use a pre-meeting survey to capture board member questions and focus the discussion; and how you will measure whether the redesign is working (board engagement survey, attendance rates, decision quality).","tags":["board-development","governance","meetings","strategic-planning","immigration","phoenix"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-54","title":"Executive Director Annual Performance Review Process","prompt":"You are the Board Chair of a 30-year-old housing development nonprofit in Cleveland with a $6 million annual budget. Your Executive Director has been in the role for four years, and your board has never had a structured performance review process — feedback has been informal and sporadic, and the ED has expressed frustration about unclear expectations. Design a complete Executive Director annual performance review process (maximum 2,000 words) that: defines the review structure (a 360-degree process combining board self-assessment of its own support for the ED, ED self-assessment, programmatic outcomes review, and financial performance review); creates the specific evaluation rubric — identify eight dimensions to evaluate (leadership and vision, financial management, fundraising, external relationships, program quality, staff management, board partnership, strategic execution) and define what exceeds expectations, meets expectations, and needs development looks like for each; describes the board committee that will lead the process (who, what role); outlines the timeline (when in the year the review happens, how many weeks it takes); explains how the review connects to the ED's compensation decision; and provides a guide for the face-to-face review conversation — what the Board Chair should say, how to deliver critical feedback constructively, and how to agree on goals for the coming year.","tags":["board-development","governance","executive-director","performance-review","housing","cleveland"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-55","title":"Nonprofit Conflict of Interest Policy and Procedures","prompt":"You are the General Counsel (part-time pro bono) for a 25-staff community development financial institution in rural Appalachia with a 15-member board that includes local bank executives, a real estate developer, and several small business owners who are also active borrowers from the CDFI. Your current conflict of interest policy is a one-paragraph statement that has never been operationalized. Write a complete Conflict of Interest Policy and Procedures document (maximum 2,500 words) that: defines what constitutes a conflict of interest for board members, staff, and volunteers — including direct financial interests, family relationships, and organizational relationships; creates a tiered disclosure and recusal framework (annual disclosure forms, meeting-level disclosure protocol, the recusal procedure for votes); addresses the specific high-risk scenarios common to CDFIs (a board member whose business is applying for a loan, a board member affiliated with an organization your CDFI is considering partnering with, a board member who is also a vendor); drafts the annual conflict of interest disclosure form (include the actual form language); specifies how conflicts will be documented in board minutes; and describes the escalation procedure when a potential conflict is identified mid-meeting. Reference the IRS Form 990 Part VI conflict of interest disclosure requirements and the Sarbanes-Oxley principles that apply to nonprofits.","tags":["board-development","governance","conflict-of-interest","CDFI","compliance","legal"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-56","title":"Board-Staff Partnership Agreement","prompt":"You are the Executive Director of a 50-staff refugee services organization in Minneapolis that has experienced recurring friction between board members and program staff — two board members have directly contacted program managers to redirect work priorities without informing the ED, and one staff member submitted a complaint to the board chair about a personnel decision that should have gone through the ED first. Write a Board-Staff Partnership Agreement document (maximum 1,500 words) that will be adopted by the board and shared with all staff. The document must: define clearly where the board's authority begins and ends (policy, strategy, fiduciary oversight, ED hiring and evaluation) and where the ED's authority begins and ends (all operational decisions, staff management, program implementation, day-to-day financial management); establish the sole point of accountability relationship between the board and the organization (the board manages through and to the ED, not around the ED); specify the protocols for board members who want information from staff (must go through the ED or with ED's explicit knowledge); address the protocol for staff who want to raise concerns with the board (a narrow, defined process for serious concerns that does not undermine the ED's management authority); and include a section on board member behavior standards when interacting with staff at events, site visits, and in the community.","tags":["board-development","governance","board-staff-relations","accountability","minneapolis","refugee-services"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-57","title":"Reserve Fund Policy Development","prompt":"You are the Finance Committee Chair at a 22-year-old domestic violence services organization in Austin, Texas with a $3.2 million annual budget, $420,000 in unrestricted net assets, and a heavy reliance on a single Texas Health and Human Services contract that represents 58% of revenue. Your board has no formal reserve policy and no consensus on what reserves are for. Write a complete Reserve Fund Policy document (maximum 1,500 words) that: makes the case for reserves by quantifying your specific organizational risks (contract non-renewal timeline, government payment delays, potential emergency costs); defines the types of reserves you will establish (operating reserve — three months of operating expenses as your target, defined as $800,000; capital reserve for facility and equipment needs; and a crisis/opportunity reserve); sets the target amount for each reserve type and explains how the targets were calculated; defines what events trigger a drawdown of each reserve type and the governance process required to authorize a drawdown (board vote, finance committee approval, ED authorization); establishes the annual process for reviewing reserve levels, deciding whether to build reserves or deploy surplus, and reporting reserve status to the full board; and describes where reserves will be held (money market account, short-term CDs, or other instruments) consistent with your investment policy.","tags":["financial-management","governance","reserve-fund","financial-sustainability","domestic-violence","austin"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-58","title":"Annual Operating Budget Development Process","prompt":"You are the Finance Director at a 35-staff environmental advocacy organization in Seattle with a $4.5 million annual budget funded through a mix of foundation grants (45%), individual donors (30%), government contracts (15%), and earned revenue from consulting and events (10%). Your current budget process is a top-down exercise where the ED and Finance Director set numbers without meaningful program staff input, resulting in staff who feel no ownership of their budgets and don't flag variances until they are serious. Design a completely redesigned annual budget development process (maximum 2,000 words) that: maps out a four-month budget calendar from July through October for a January 1 fiscal year start, specifying who is responsible for what at each stage; describes how program managers will build their program budgets from the bottom up using a budget template you will describe (revenue projections by grant with probability weighting, direct expenses by category, staff time allocation by FTE); explains your revenue forecasting methodology for each revenue stream including your probability-weighted grant pipeline approach; describes the Finance Committee review process and the criteria for resolving competing budget requests when total requests exceed projected revenue; and includes a section on what budget variance reporting program managers will receive monthly and how you will use budget-to-actual conversations to build financial literacy across the organization.","tags":["financial-management","budgeting","nonprofit-finance","seattle","environmental","budget-process"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-59","title":"Single Audit Preparation Guide","prompt":"You are the Controller at a 60-staff community action agency in rural Mississippi that expends $4.2 million in federal funds annually across five programs (CSBG, LIHEAP, Head Start, USDA Child and Adult Care Food Program, and a HUD emergency solutions grant), triggering the requirement for an annual single audit under 2 CFR 200 Subpart F. Your audit is scheduled to begin in four months and you have a new staff auditor joining your team who has never been through a single audit. Write a comprehensive single audit preparation guide (maximum 2,500 words) that: explains what a single audit is and how it differs from a financial statement audit, including the schedule of expenditures of federal awards (SEFA) and what must be included; describes the major program determination process and explains which of your five programs will likely be selected as major programs based on the Type A threshold calculation; creates a month-by-month preparation timeline for the four months before fieldwork begins; specifies the document packages the auditor will request for each major program and how to organize them (award documents, drawdown records, subrecipient monitoring documentation, eligibility files, procurement records); describes how to prepare program staff for auditor interviews; and explains what findings, questioned costs, and material weaknesses mean and your internal escalation protocol if the auditor identifies a potential finding during fieldwork.","tags":["financial-management","single-audit","federal-compliance","2CFR200","community-action","mississippi"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-60","title":"Cost Allocation Plan for a Multi-Program Nonprofit","prompt":"You are the CFO at a 75-staff urban health and human services nonprofit in Philadelphia operating six distinct programs (primary care clinic, HIV case management, re-entry services, youth mentoring, housing counseling, and community organizing) funded by a mix of Medicaid billing, federal grants, state contracts, foundation grants, and individual donations. Your organization has been allocating shared costs (executive staff, finance, HR, IT, facilities) using a simple headcount method that your federal program officer has flagged as potentially not reflecting actual cost drivers. Write a complete Cost Allocation Plan document (maximum 2,000 words) that: explains the regulatory framework for cost allocation under 2 CFR 200 (the three tests: allowable, allocable, reasonable); describes the shared cost categories you need to allocate and the current headcount method; proposes a revised cost allocation methodology using multiple allocation bases that better reflect actual cost drivers (square footage for facilities, IT user count for technology costs, HR transactions for HR costs, grant revenue percentage for finance and executive time); provides a worked example showing how the new methodology changes the cost allocation for two programs compared to the old method; addresses how you will document and defend the methodology to federal auditors; and describes the process for reviewing and updating the methodology annually.","tags":["financial-management","cost-allocation","federal-grants","nonprofit-finance","philadelphia","2CFR200"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-61","title":"Staff Recruitment Strategy for Hard-to-Fill Program Roles","prompt":"You are the HR Director at a 45-staff child welfare nonprofit in St. Louis that operates foster family recruitment, training, and support services. You have three open Licensed Clinical Social Worker positions that have been vacant for an average of six months each, contributing to caseload overload and two staff departures. Starting salary is $52,000–$58,000, which is 15% below the market rate for hospital and private practice LCSW roles in St. Louis. Write a comprehensive recruitment strategy (maximum 2,000 words) that honestly confronts the compensation gap and proposes realistic solutions: a salary analysis comparing your current range to Missouri LCSW market rates and a proposal for a revised range your board could approve; a total compensation narrative you can present to candidates that frames non-salary benefits honestly (loan forgiveness eligibility under PSLF, licensure supervision, flexible scheduling, meaningful mission) without misrepresenting what you offer; three specific sourcing strategies beyond standard job boards (MSW program partnerships with Washington University and St. Louis University, targeted outreach to recently licensed social workers in private practice who are burning out, partnership with the Missouri chapter of NASW); your candidate screening and interview process timeline; and your onboarding plan for the first 90 days that specifically addresses the caseload and support concerns that have driven recent departures.","tags":["volunteer-staff-management","recruitment","social-work","HR","st-louis","compensation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"ngo-62","title":"Staff Wellbeing and Burnout Prevention Program","prompt":"You are the People and Culture Director at a 55-staff domestic violence and sexual assault services organization in Albuquerque, New Mexico where 68% of your staff reported feeling burned out in your most recent annual staff survey, your turnover rate is 42% annually (compared to a sector average of 25–30%), and two staff members have gone on extended medical leave for stress-related conditions in the past year. Your ED has approved a budget of $35,000 for a one-year staff wellbeing initiative. Write a comprehensive staff wellbeing program design (maximum 2,000 words) that: diagnoses the root causes of burnout in your specific organization — distinguish between secondary traumatic stress from direct client contact, organizational stressors (workload, management quality, unclear roles), and systemic sector underfunding; proposes a three-tier intervention model (organizational-level changes to policies and workload, team-level practices like structured peer support and supervision quality, individual-level resources like EAP promotion and self-care stipends); specifies the four highest-impact changes you will implement in the first 90 days with your $35,000 budget; describes how you will measure program impact (staff survey repeated at 6 and 12 months, tracking turnover and sick leave rates, optional participation tracking); and addresses the tension between investing in staff wellbeing and the board's expectation that the money goes to clients.","tags":["volunteer-staff-management","staff-wellbeing","burnout","HR","domestic-violence","albuquerque"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-63","title":"Volunteer Program Design for Skills-Based Service","prompt":"You are the Volunteer Program Manager at a community legal aid organization in Chicago that serves 3,400 low-income clients per year with housing, family law, and public benefits legal matters. You have a pool of 80 pro bono attorneys from large firms who have expressed interest in volunteering, but your current volunteer program consists only of one-off clinic shifts and you lose most attorneys after one engagement because the experience is not well-organized enough to meet their firms' pro bono reporting standards. Design a restructured skills-based volunteer program (maximum 2,000 words) that: creates three distinct volunteer engagement tracks (clinic attorney for one-time document review clinics, case mentor for attorneys who will guide a junior attorney through a full case, and pro bono case attorney for experienced attorneys taking full case assignments); specifies the screening, training, and onboarding process for each track including CLE credit eligibility; describes the case management support structure that makes it possible for a volunteer attorney to handle a case without needing to be a nonprofit law expert; creates the feedback and recognition system tied to your firm partners' pro bono reporting requirements (hours, case outcomes, client impact); and proposes a retention strategy targeting the 20 most engaged volunteer attorneys for a deeper ongoing partnership including a quarterly pro bono advisory committee.","tags":["volunteer-staff-management","pro-bono","volunteer-program","legal-aid","chicago","skills-based-volunteering"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-64","title":"Performance Management System for Frontline Staff","prompt":"You are the HR Manager at a 65-staff community health center network in rural Texas (Brownsville area) serving predominantly uninsured and Medicaid patients, with a workforce that includes community health workers, medical assistants, patient navigators, and administrative staff. Your current performance management approach consists of an annual written review that most supervisors complete late and staff experience as punitive rather than developmental. Design a new performance management system (maximum 2,000 words) that: replaces the annual review with a continuous performance management model (monthly 30-minute check-ins, quarterly goal reviews, annual comprehensive review); creates a goal-setting framework for frontline positions using a combination of quantitative metrics (patient visit completion rates, screening completion rates, care gap closure) and qualitative competency assessments (patient communication, teamwork, cultural responsiveness); trains supervisors on how to deliver effective feedback — include the specific feedback model (SBI: Situation-Behavior-Impact) with two worked examples from your context; defines what a Performance Improvement Plan looks like, when it is used, what support it provides, and how it is distinct from discipline; addresses the language access needs of supervisors and staff who are more comfortable in Spanish; and describes how the performance management system connects to compensation decisions and career development pathways.","tags":["volunteer-staff-management","performance-management","HR","community-health","texas","frontline-staff"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-65","title":"Organizational Culture Assessment and Action Plan","prompt":"You are the new Chief People Officer at a 90-staff national advocacy organization in Washington D.C. that advocates for affordable housing policy. You were hired six months ago, in part because a staff survey conducted before your arrival revealed serious concerns: 61% of staff of color reported experiencing microaggressions from colleagues, 54% of all staff reported that managers do not provide clear feedback, and staff turnover among directors and managers is 38%. Your ED has asked you to present the board with a 12-month culture action plan. Write the complete action plan document (maximum 2,500 words) that: presents the diagnostic findings from the staff survey honestly without minimizing the severity; identifies the three highest-priority culture issues and the systemic causes (not individual bad actors) behind them; proposes 12-month action steps for each priority area — for the racial equity concerns specifically, describe the difference between diversity training (which research shows limited effectiveness) and structural interventions (compensation equity audits, promotion process redesign, ERG formation with real budget and influence); describes how you will hold managers accountable for culture change without making them defensive; specifies your measurement approach (repeat survey at 12 months, track promotion rates by race and gender, track turnover by demographic); and addresses what to do if you uncover a situation requiring HR investigation during the culture work.","tags":["volunteer-staff-management","organizational-culture","DEI","HR","national-advocacy","washington-dc"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-66","title":"Staff Compensation Equity Audit","prompt":"You are the HR Director at a 48-staff environmental justice nonprofit in Los Angeles with a $5 million budget. Your organization has not done a compensation analysis in six years, your salary ranges are not published internally, and several staff members of color in program roles have raised concerns that white colleagues in similar roles are paid more. Your Executive Director has approved a compensation equity audit. Write a complete compensation equity audit methodology and report template (maximum 2,000 words) that: describes the data you will collect for each position (job title, department, level, years in role, years of experience, education, performance rating, base salary, total compensation) and how you will code race, gender, and other demographic variables using self-identification data from your HRIS; describes the statistical analysis you will conduct (regression analysis controlling for legitimate factors like experience and performance to isolate unexplained pay gaps, plus simple descriptive analysis by demographic group); explains how you will interpret the results — what constitutes a statistically significant gap, what pay gap percentage is considered actionable, and what factors are and are not legitimate explanations for differences; describes the decision-making process for remediation (who decides, what budget is required, what the timeline is for adjustments); and provides guidance on how to communicate the audit findings to staff — how much transparency is appropriate and how to handle the communication with individuals who are found to be underpaid.","tags":["volunteer-staff-management","compensation-equity","HR","DEI","los-angeles","pay-equity"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-67","title":"Memorandum of Understanding for Program Partnership","prompt":"You are the Program Director at a workforce development nonprofit in Cincinnati that has agreed to co-deliver a new 12-month Green Jobs training program with a local community college (Cincinnati State Technical and Community College) and a regional employer association (the Greater Cincinnati Energy Consortium). The partnership involves your organization leading recruitment and wraparound support services, Cincinnati State providing the technical training and credentials, and the employer association providing paid internship placements. You have agreed on the concept but no formal agreement exists. Write a complete Memorandum of Understanding (maximum 2,500 words) covering: the recitals section (who the parties are, the background of the partnership, the shared goal); definitions of key terms (participant, training cohort, wraparound services, employer partner); the responsibilities of each party in specific, operational detail (not vague language like 'will support' but specific deliverables, timelines, and staff roles); data sharing provisions (what participant data will be shared between organizations, under what consent framework, with what security requirements, and who owns aggregate outcome data); financial arrangements (who receives the grant funds, how funds flow between partners, what happens if a partner fails to deliver); governance of the partnership (a joint steering committee, meeting frequency, decision-making process, dispute resolution); and termination provisions (how a partner exits the agreement, what happens to participants mid-program, how assets and data are handled at termination).","tags":["partnerships","coalition-building","MOU","workforce-development","cincinnati","partnership-agreement"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"ngo-68","title":"Collective Impact Initiative Design","prompt":"You are the backbone organization director for a new collective impact initiative in Tulsa, Oklahoma focused on reducing the third-grade reading proficiency gap between white students and Black and Native American students in Tulsa Public Schools, where only 19% of Black third-graders and 17% of Native American third-graders are reading at grade level compared to 52% of white students. The initiative involves 14 organizations including TPS, the Tulsa Community Foundation, early childhood programs, library services, and family support organizations. The initiative is in its first six months and you need to move from a shared vision statement to a functioning collective impact structure. Write a complete collective impact design document (maximum 2,500 words) following the FSG collective impact framework that: defines your common agenda (the shared goal, the shared theory of change, and the boundaries of what is in and out of scope for the initiative); describes how you will establish shared measurement (the five indicators all 14 organizations will track and report on, the data platform you will use, and the data governance agreement); outlines the mutually reinforcing activities framework (mapping what each organization will contribute and where you will coordinate rather than duplicate); describes the continuous communications protocol between initiative members; and defines the backbone organization's specific roles (coordination, data facilitation, communications, funder relations) and what it explicitly does NOT do (does not direct the work of member organizations, does not speak for the initiative without member approval).","tags":["partnerships","coalition-building","collective-impact","FSG-framework","literacy","tulsa"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-69","title":"Subgrant Management System for Pass-Through Funding","prompt":"You are the Grants Manager at a statewide intermediary organization in Georgia that has received a $2.5 million, three-year grant from the Annie E. Casey Foundation to re-grant to 18 community-based organizations across rural Georgia working on family economic stability. This is your organization's first time managing a subgrant program at this scale. Write a complete subgrant management system design document (maximum 2,000 words) covering: the subgrant application process (your RFP design, eligibility criteria, review and selection process, and how you will weight applications from organizations led by and serving communities of color); the subgrant agreement template provisions (grant amount, reporting requirements, allowable and unallowable costs, audit requirements for subgrantees receiving over $750,000, data sharing, intellectual property, termination); your subgrantee monitoring approach (desk review of financial and programmatic reports, site visit schedule, technical assistance office hours); your financial management of the pass-through funds (drawdown requests from Casey, subgrantee payment triggers, how you will handle underspending or overspending by subgrantees); and your approach to building the capacity of smaller subgrantees who have never managed a grant of this size — specifically, the three most common compliance failures in first-time subgrantees and how your system will prevent them.","tags":["partnerships","subgrant-management","pass-through","annie-casey","georgia","grants-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-70","title":"Coalition Communications and Message Discipline Strategy","prompt":"You are the Communications Director for a statewide education equity coalition in Michigan with 32 member organizations ranging from large teachers unions to small parent advocacy groups. Your coalition is running a two-year campaign to pass legislation requiring universal school breakfast in Michigan public schools. A recent campaign setback occurred when two member organizations made conflicting public statements to reporters — one emphasized the nutritional benefits and the other emphasized cost savings to families, and a reporter wrote a story about the 'divided coalition.' Write a complete coalition message discipline strategy (maximum 2,000 words) that: conducts a message audit — identify the three core audiences (state legislators, parents of school-age children, and business community) and what each audience cares about most; develops a unified message architecture with one headline message (the 'north star' that all coalition members will use), two supporting messages, and one proof point per audience; establishes the message discipline infrastructure (a coalition communications committee with one representative per major member bloc, a rapid response protocol for media inquiries, a shared messaging guide distributed to all 32 members); creates the protocol for what coalition members can say independently vs. what requires coalition approval; and designs a message training workshop for member organization communications staff (describe the one-page materials and the two-hour agenda).","tags":["partnerships","coalition-building","message-discipline","education-equity","michigan","communications"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-71","title":"Funder Collaborative Design for Place-Based Grantmaking","prompt":"You are the Program Officer at a community foundation in the Kansas City metropolitan area that has convened four other local foundations (the Hall Family Foundation, the Ewing Marion Kauffman Foundation, the United Way of Greater Kansas City, and the Kansas City Missouri Health Foundation) to pilot a three-year place-based funding collaborative focused on the 64130 zip code, one of the most economically distressed zip codes in Missouri. The five funders have agreed to pool $3 million over three years. Write a funder collaborative design document (maximum 2,000 words) that: defines the governance structure (a collaborative steering committee, decision-making process, role of the community foundation as fiscal agent, dispute resolution); establishes the collaborative's grantmaking philosophy — specifically how you will ensure community residents in 64130 have meaningful input into funding decisions, not just token consultation; describes the grant portfolio strategy (mix of organizational operating support vs. project grants, how you will decide between investing in a few large organizations vs. many small ones, your approach to funding organizations led by residents of 64130); addresses the funder alignment challenges honestly — how you will handle it when funders have conflicting priorities, different risk tolerances, and different reporting requirements; and describes your learning and evaluation approach for the collaborative itself (not just for grantees), including what you will do if the collaborative is not working after 18 months.","tags":["partnerships","funder-collaborative","place-based-grantmaking","kansas-city","community-foundation","grantmaking"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-72","title":"Cross-Sector Partnership Negotiation Preparation","prompt":"You are the Executive Director of a 30-staff food access nonprofit in Denver that operates four community gardens and a mobile produce distribution program reaching 2,800 low-income households. The Denver Housing Authority has approached you about a partnership to place community gardens on three DHA property sites and integrate your mobile market into their resident services program. This is a significant opportunity but DHA is a large government agency with its own procurement requirements, liability concerns, and bureaucratic timeline. Write a complete partnership negotiation preparation document (maximum 1,800 words) that: defines your organization's interests (not just positions) — what outcomes are truly essential vs. what you are willing to compromise on; identifies DHA's likely interests based on what you know about their resident satisfaction goals, USDA SNAP-Ed funding requirements, and their new strategic plan; maps the negotiation terrain — what are the three most likely sticking points (liability for garden infrastructure damage, which organization hires and supervises the garden staff, exclusivity vs. your ability to partner with other housing providers); proposes your opening offer and your BATNA (Best Alternative to No Agreement); and provides a one-page partnership term sheet you will bring to the initial negotiation meeting covering: term length, site access and maintenance responsibilities, staffing, revenue and cost sharing, data ownership, and mutual exit provisions.","tags":["partnerships","coalition-building","negotiation","food-access","denver","housing-authority"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-73","title":"Strategic Planning Process Design","prompt":"You are the Executive Director of a 28-year-old arts education nonprofit in Philadelphia that provides in-school residencies and after-school programs serving 6,200 K–12 students across 42 schools. Your current strategic plan expired 18 months ago and you are launching a new three-year planning process. Your last strategic plan was developed by a consultant who worked primarily with the board and senior staff with minimal community voice, and the resulting plan felt disconnected from the teachers and students you serve. Design a complete 9-month strategic planning process (maximum 2,000 words) that: describes a genuinely participatory process with specific mechanisms for student, teacher, school administrator, and alumni voices to shape the plan (not just validate it); specifies the staff and board working groups with their roles and decision-making authority; outlines the environmental scan you will conduct (SWOT analysis, competitive analysis, demographic trends in Philadelphia school enrollment, peer organization benchmarking against three comparable arts education organizations in other cities); describes the strategic priorities development process — how you will move from hundreds of input data points to three to five strategic priorities; addresses the financial modeling component — how each strategic priority will be costed and connected to a revenue strategy; and describes the final plan format and a launch and communication strategy that builds genuine organizational buy-in rather than a document that sits on a shelf.","tags":["organizational-development","strategic-planning","arts-education","philadelphia","participatory-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"ngo-74","title":"Executive Transition Planning and Management","prompt":"You are the Board Chair of a 35-year-old community health advocacy organization in Atlanta whose founding Executive Director has announced she will retire in 14 months. The ED has been in the role for 18 years and is the primary relationship holder for your five largest foundation funders, your key state agency partners, and most of your major individual donors. She is committed to a successful transition. Write a complete executive transition plan (maximum 2,500 words) that: structures the transition into three phases — departure preparation (months 1–6), recruitment and selection (months 5–9, overlapping), and onboarding and handover (months 9–14); describes the knowledge capture process in Phase 1 (what institutional knowledge needs to be documented, the format for capturing it, how donor relationships will be introduced to the board and other senior staff before the ED leaves); outlines the board's search process in detail (internal vs. external search decision framework, search committee composition and representation, whether to use an executive search firm — recommend one of three options with cost estimates, candidate profile development, a structured interview and reference check process); addresses the specific risk of donor attrition during the transition and your mitigation strategy; and describes the 90-day onboarding plan for the new Executive Director including early wins, relationship priorities, and how the departing ED will be available without undermining the new leader's authority.","tags":["organizational-development","executive-transition","succession-planning","community-health","atlanta","leadership"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-75","title":"Organizational Financial Sustainability Assessment","prompt":"You are the Chief Financial Officer at a 42-staff immigrant integration services organization in Minneapolis with a $3.8 million annual budget that has experienced three consecutive years of operating deficits totaling $340,000, drawing down your reserve fund from $620,000 to $280,000. Your largest funder, the Otto Bremer Trust, has expressed concern and asked for a financial sustainability plan before renewing their $300,000 annual grant. Write a complete financial sustainability assessment and plan (maximum 2,500 words) that: conducts an honest financial diagnostic — analyze your revenue concentration risk (identify that your top three funders represent 61% of revenue), your expense structure (identify that personnel costs are 78% of total expenses with limited flexibility), and your structural deficit (distinguish between a structural deficit caused by overspending vs. a strategic deficit caused by deliberate investment in growth); proposes a three-year financial sustainability plan with specific revenue diversification targets (reduce top-funder concentration to 45% by Year 3, launch an individual giving program targeting $180,000 in Year 1 growing to $320,000 by Year 3, develop two new fee-for-service revenue streams from your legal services and workforce training); presents a Year 1 expense reduction scenario that does not reduce program capacity; and addresses the difficult conversation with Otto Bremer Trust — what you will say, what you will commit to, and what you are asking them to commit to.","tags":["organizational-development","financial-sustainability","financial-management","minneapolis","immigrant-services","turnaround"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-76","title":"Technology Systems Upgrade Strategy","prompt":"You are the Operations Director at a 55-staff community services nonprofit in Detroit operating a food pantry, emergency financial assistance, employment services, and housing navigation programs. Your technology infrastructure has not been significantly updated in eight years. You are using four separate databases (Charity Tracker for food pantry, HMIS for housing, a local Access database for employment services built by a former staff member, and QuickBooks for finance) that do not talk to each other, requiring staff to enter the same client data in multiple systems. You have $120,000 from a capacity-building grant and 18 months to address your data infrastructure. Write a complete technology upgrade strategy (maximum 2,000 words) that: maps your current data architecture and identifies the three biggest operational costs of the current siloed system (staff time on duplicate data entry, inability to track cross-program client outcomes, inability to report unified program impact to funders); defines your functional requirements for a new case management system (integration with HMIS, food pantry module, employment services tracking, outcome reporting capability, ease of use for frontline staff with limited tech comfort); evaluates three candidate platforms (Apricot by Bonterra, Efforts to Outcomes, and Salesforce NPSP with a custom build) against your requirements and budget; recommends one with total cost of ownership analysis over five years; and proposes a data migration, training, and change management plan that acknowledges the significant organizational disruption a systems change will cause.","tags":["organizational-development","technology","data-systems","capacity-building","detroit","nonprofit-operations"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-77","title":"Merger Feasibility Assessment","prompt":"You are the Executive Director of a 20-staff affordable housing counseling agency in Cleveland that has been approached by a larger 80-staff community development corporation (CDC) about a potential merger. The CDC argues the merger would create efficiencies, expand housing counseling capacity, and strengthen the combined organization's position with funders. You are skeptical but open-minded. Your board has asked you to lead a merger feasibility assessment and present a recommendation in 90 days. Write a complete merger feasibility assessment framework (maximum 2,000 words) that: defines the questions you need to answer before you can make a recommendation (mission alignment, cultural compatibility, financial health of the CDC, governance structure post-merger, staff employment protections, brand and community identity implications); describes the due diligence process — specifically what financial and legal documents you will review, which stakeholders you will interview (staff, board members, clients, funders, peer organizations), and how you will assess organizational culture compatibility; develops the decision criteria your board will use to evaluate the merger — what outcomes would constitute a successful merger and what would constitute a failed one at Year 1, Year 3, and Year 5; addresses the power dynamics honestly — as the smaller organization, how do you negotiate a merger that protects your mission and your staff rather than being absorbed and dissolved; and identifies the three scenarios (full merger, shared services agreement, remaining independent) and proposes a recommendation framework.","tags":["organizational-development","merger","strategic-planning","affordable-housing","cleveland","nonprofit-consolidation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-78","title":"Program Evaluation Capacity Building Plan","prompt":"You are the Evaluation Consultant working with a 25-staff youth workforce development organization in Oakland, California that runs summer jobs, year-round work readiness training, and alumni coaching. The organization has strong program instincts and compelling stories but no systematic data collection, no logic model, and no way to answer a funder's question about what outcomes they are achieving. The Executive Director has secured a $75,000 Zellerbach Family Foundation capacity-building grant specifically to build evaluation capacity over 18 months. Write a complete evaluation capacity building plan (maximum 2,000 words) that: assesses the organization's current evaluation readiness (data culture, staff data skills, existing data collection practices, CRM capabilities); defines what 'good enough' evaluation capacity looks like for a 25-staff organization — not a research-grade system but a credible, sustainable system that answers the questions funders and staff actually have; proposes a four-phase capacity building sequence (Phase 1: logic model development with staff, Phase 2: indicator selection and data collection tool design, Phase 3: system implementation and staff training, Phase 4: learning to use data for program improvement); describes how you will build internal ownership so the evaluation system survives after the consultant engagement ends; and provides a specific 18-month timeline, a budget breakdown of the $75,000, and the three biggest risks to the capacity building effort and how you will mitigate them.","tags":["organizational-development","evaluation-capacity","youth-workforce","oakland","capacity-building","zellerbach"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-79","title":"Localization and Local Partnership Transition Strategy","prompt":"You are the Country Director for an international NGO that has operated in rural Guatemala for 22 years, implementing nutrition, maternal health, and income generation programs. Your headquarters in Washington D.C. has adopted a localization commitment: within five years, all program implementation in Guatemala will be led by Guatemalan civil society organizations, with your organization shifting from implementer to technical advisor and capacity builder. You are one year into this transition and have identified three potential local partner organizations to take on program delivery. Write a complete localization transition strategy (maximum 2,500 words) that: honestly assesses the state of the three potential local partners — their current organizational strengths and capacity gaps across financial management, program quality, M&E, HR, and governance; proposes a differentiated capacity support plan for each partner tailored to their specific gaps; addresses the hardest questions in localization honestly — what happens to your current Guatemalan national staff as you transition from implementer to advisor, how you ensure the transition does not disrupt services to beneficiaries, and how you manage the power dynamics inherent in an international NGO 'deciding' which local organizations are ready; describes how you will renegotiate your donor relationships to allow prime awards to go directly to local organizations rather than flowing through your organization; and defines what your organization's role looks like in Year 5 — what specific value-add justifies your continued presence.","tags":["organizational-development","localization","international-NGO","guatemala","local-partnership","capacity-building"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-80","title":"Revenue Diversification Strategy for a Government-Dependent Nonprofit","prompt":"You are the Executive Director of a 38-staff workforce development organization in rural Appalachian Kentucky with a $2.9 million annual budget that is 84% dependent on Workforce Innovation and Opportunity Act (WIOA) funding administered through the Kentucky Education and Workforce Development Cabinet. A new state administration is proposing to redesign the WIOA service delivery system in a way that could reduce your contract by 40% in 18 months. Write a complete 24-month revenue diversification plan (maximum 2,000 words) that: maps your current revenue and identifies the specific single-point-of-failure risks (contract concentration, payment lag, restricted funding, political vulnerability); identifies four viable alternative revenue streams for your specific context (employer training fees from regional coal-to-clean energy transition employers, Appalachian Regional Commission grants for economic transition, an individual donor cultivation program leveraging your local board relationships, and a fee-for-service technical assistance program selling your workforce training model to peer organizations in other states); for each revenue stream, provides a 24-month development plan with realistic Year 1 and Year 2 revenue projections, the staff investment required, and the key risks; and concludes with a cash flow analysis showing when alternative revenues will be sufficient to offset a 40% WIOA contract reduction and what interim bridge strategies you will use.","tags":["organizational-development","revenue-diversification","financial-sustainability","appalachia","WIOA","workforce-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-81","title":"Nonprofit Financial Dashboard for Board Reporting","prompt":"You are the Finance Director at a 40-staff immigrant advocacy and direct services organization in Chicago with a $3.5 million annual budget. Your current board financial reporting consists of a 12-page spreadsheet that most board members do not read before meetings, and your Finance Committee meetings frequently get bogged down in line-item questions rather than strategic financial oversight. Design a complete one-page visual financial dashboard for board meetings (maximum 1,500 words describing the dashboard design in detail) that: identifies the six financial indicators most critical for board-level oversight of your organization (and explains why these six and not others) — recommend: operating reserve ratio, budget vs. actual variance by major revenue category, pipeline revenue at risk (grants in final reporting year without renewal confirmed), days cash on hand, program expense ratio, and fundraising cost per dollar raised; specifies the visual format for each indicator (traffic light status, trend line, bar chart against target) and the specific data source and update frequency for each; describes the one-page layout with section labels, relative space allocation, and visual hierarchy; explains what narrative context (maximum 50 words per indicator) should accompany the numbers; and provides the specific trigger thresholds that shift an indicator from green to yellow to red for each of your six indicators, with the specific board action that yellow and red status should prompt.","tags":["financial-management","board-reporting","dashboard","nonprofit-finance","chicago","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-82","title":"Restricted Grant Fund Tracking and Reporting System","prompt":"You are the Controller at a 25-staff marine conservation nonprofit in Seattle with a $2.2 million annual budget funded by 38 active grants with varying restriction levels, reporting periods, and allowable cost rules. Your Executive Director has just received an angry call from a program officer at the David and Lucile Packard Foundation because your semi-annual report showed expenditures in categories that are not in the approved Packard budget without prior approval or explanation. You have also discovered that three other grants have similar unexplained variances. Design a complete grant fund tracking and reporting system (maximum 2,000 words) that: diagnoses the root cause of the Packard situation (likely: no grant setup process, no budget-to-actual tracking at the grant level, no variance review before submitting reports); creates a grant opening checklist specifying what must happen in the first two weeks after an award is received (grant file setup in your accounting system with correct fund codes, award document review and budget loading, grant compliance summary card created and distributed to all relevant staff); describes the monthly grant financial monitoring routine (who runs the grant-level budget vs. actual report, what variance threshold triggers a review, who approves budget modifications before they happen); creates the grant close-out process to ensure you never submit a final report without reconciling all costs; and proposes the two or three tools your specific organization needs to prevent future compliance issues given your 38-grant portfolio.","tags":["financial-management","grant-tracking","restricted-funds","compliance","marine-conservation","seattle"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-83","title":"Internal Controls Assessment for Fraud Prevention","prompt":"You are the new Executive Director of a 15-staff community arts nonprofit in New Orleans with a $1.1 million annual budget. Three months into your role, your auditor has flagged a pattern of unusual petty cash reimbursements submitted by a former operations manager who left abruptly six months ago. The board is alarmed and wants an internal controls review. Write a complete internal controls assessment and strengthening plan (maximum 2,000 words) that: explains what internal controls are and why small nonprofits are disproportionately vulnerable to fraud (limited staff for segregation of duties, high trust culture, board that does not review detailed financials); conducts an assessment of your current internal controls across five risk areas — cash disbursements, credit cards and expense reimbursements, payroll and timekeeping, revenue and cash receipts, and information technology access; identifies the three highest-risk control gaps in a 15-person nonprofit with only one finance staff person and proposes compensating controls that work with your staff size (e.g., board treasurer reviews all checks over $2,500, Executive Director approves all credit card statements before processing, dual signatures required on checks over $5,000); describes the board's oversight role in internal controls including specific Finance Committee procedures; and outlines what additional investigation of the former operations manager situation you should commission and when to involve law enforcement or your insurance carrier.","tags":["financial-management","internal-controls","fraud-prevention","governance","community-arts","new-orleans"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-84","title":"Capital Campaign Feasibility and Financial Modeling","prompt":"You are the Executive Director of a 50-year-old community center in St. Paul, Minnesota that serves 4,800 households annually through early childhood education, senior services, and immigrant integration programs. You are exploring a $4.5 million capital campaign to purchase and renovate your current leased facility, which the landlord has indicated may be sold in the next three years. Write a complete capital campaign feasibility and financial modeling document (maximum 2,500 words) that: builds the financial case for ownership vs. continued leasing — compare your current annual lease cost ($186,000) against estimated ownership costs (mortgage, maintenance, reserves), projected equity buildup, and the programmatic value of facility security; describes a feasibility assessment process you will conduct over the next six months before committing to a campaign (board readiness assessment, donor capacity research using wealth screening on your top 200 donors, funder landscape analysis, peer organization interviews about their capital campaigns); presents a gift pyramid for a $4.5 million campaign showing how many gifts at each level are needed (from a lead gift of $750,000 down to gifts of $1,000), which level must be secured before publicly launching, and where those gifts are most likely to come from; describes your campaign team structure (campaign chair, volunteer cabinet, staff roles); and identifies the three biggest risks to campaign success and your contingency plan if you reach only 65% of goal by the campaign deadline.","tags":["financial-management","capital-campaign","facilities","community-center","st-paul","fundraising"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-85","title":"Earned Revenue Business Plan for Nonprofit Fee-for-Service","prompt":"You are the Director of Innovation at a 30-staff workforce development organization in Cincinnati that has developed a highly effective job readiness and placement model for people with barriers to employment. Several peer organizations and workforce systems in other cities have asked you to help them replicate your model. Your ED sees this as both a revenue opportunity and a mission multiplier. Write a complete earned revenue business plan (maximum 2,000 words) for a fee-for-service technical assistance and training program that: defines the service offering precisely — a six-month replication support package including a site assessment, a three-day staff training (describe the curriculum modules), monthly coaching calls, a performance data review at month six, and a replication toolkit with all training materials; estimates your total addressable market (how many organizations in the US run similar workforce programs, what subset could pay for replication support, what they currently spend on technical assistance); builds a financial model for the business showing Year 1 revenue from four clients, Year 2 from eight clients, and Year 3 from twelve clients, with your cost structure (staff time, travel, materials), pricing ($45,000 per client in Year 1), and projected contribution margin; addresses the mission-market tension (how do you ensure fee-for-service clients are not just the well-resourced organizations, not the ones serving the highest-need populations?); and describes the governance and decision-making structure — who in your organization has authority over the fee-for-service program and how you will prevent it from consuming your core program capacity.","tags":["financial-management","earned-revenue","business-plan","workforce-development","cincinnati","fee-for-service"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-86","title":"New Program Director 90-Day Entry Plan","prompt":"You are a newly hired Program Director at a 45-staff HIV prevention and care organization in Houston, Texas, responsible for overseeing four programs (community testing, PrEP navigation, case management, and a syringe services program) with a team of 18 staff and a combined budget of $2.1 million across five funders. You are starting on day one with no prior knowledge of the organization. Write your own detailed 90-day entry plan (maximum 2,000 words) structured in three 30-day phases: Days 1–30 (listen and learn) — specify the meetings you will schedule (one-on-ones with each of your 18 direct and indirect reports, meetings with each funder's program officer, a site visit to each program location, a review session with the finance team on each grant's budget-to-actual); Days 31–60 (assess and analyze) — describe how you will synthesize what you have learned into a written assessment of each program's strengths, risks, and immediate priorities, and how you will present your preliminary findings to the ED; Days 61–90 (begin to act) — describe the specific changes or decisions you will be prepared to make by day 90, how you will build your team's trust while establishing your own leadership, and how you will communicate your leadership style and expectations to staff without replicating the approach of your predecessor. Include a section on how you will manage your own learning curve without undermining staff confidence.","tags":["volunteer-staff-management","leadership","onboarding","program-director","HIV-prevention","houston"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-87","title":"Nonprofit HR Policies Manual Update","prompt":"You are the HR Manager at a 35-staff civil rights legal organization in Atlanta that has not updated its Employee Handbook since 2018. Since then, your organization has grown from 18 to 35 staff, shifted to a hybrid work model, adopted a salary transparency policy, started offering student loan repayment assistance, and experienced two harassment complaints that revealed gaps in your complaint procedures. You have also added staff in two additional states (Tennessee and North Carolina) creating multi-state compliance obligations. Write a detailed HR Policies Manual update plan (maximum 2,000 words, not the full manual itself) that: identifies the eight policy areas that most urgently need updating or creation based on your organizational changes and new legal requirements (remote work/hybrid policy, multi-state employment law compliance for Tennessee and North Carolina, salary transparency policy and implementation, expanded anti-harassment procedures with investigation timelines, student loan repayment benefit plan document, updated FMLA and leave policy, pronouns and gender identity in the workplace policy, and lactation accommodation); for each policy area, describes the key provisions the policy must include, the applicable legal requirements, and the stakeholders who should review the draft before adoption; outlines your rollout plan (board HR committee review, legal review, all-staff rollout with a 60-minute Q&A session); and describes how you will ensure staff actually read and acknowledge the updated handbook.","tags":["volunteer-staff-management","HR-policies","employee-handbook","compliance","civil-rights","atlanta"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-88","title":"Volunteer Coordination System for a Food Bank","prompt":"You are the Volunteer Programs Manager at a regional food bank in Louisville, Kentucky that distributed 14 million pounds of food last year with the help of 8,400 individual volunteer shifts filled by individuals, corporate groups, faith communities, and school groups. Your current volunteer coordination is split between a 10-year-old spreadsheet tracking system that crashes regularly and a newer SignUpGenius account that is not integrated with your client database. Volunteer no-show rates are 22% for individual slots and 8% for group slots, and you have no systematic way to move engaged volunteers into leadership roles. Design a complete volunteer coordination system redesign (maximum 2,000 words) covering: your volunteer management software selection (evaluate VolunteerHub vs. Galaxy Digital vs. Better Impact for your specific needs — bulk group scheduling, mobile check-in, integration with Pantry Soft, automated confirmation and reminder communications, outcome reporting) and your recommendation; a volunteer recruitment strategy targeting corporate partners with Day of Caring programs (describe a specific pitch to your top five potential corporate partners by name — UPS, Humana, Brown-Forman, Kindred Healthcare, and PNC Bank); a no-show reduction strategy (analyze the 22% individual no-show rate root causes and propose three specific interventions including an automated reminder sequence); and a volunteer leadership pipeline that moves your top 15% of engaged individual volunteers into shift leader, committee member, or advocacy ambassador roles.","tags":["volunteer-staff-management","volunteer-coordination","food-bank","louisville","volunteer-management-software","engagement"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-89","title":"Staff Professional Development Program Design","prompt":"You are the Director of Talent and Culture at a 60-staff national advocacy organization in Washington D.C. that has a $6 million payroll but has invested less than $25,000 per year in staff professional development — a ratio your new CEO has called embarrassing. Your staff survey shows that career growth and professional development rank as the second most important factor for retention (after compensation) and that 42% of staff do not believe the organization invests in their growth. Your CEO has approved a $120,000 annual professional development budget and wants a structured program, not ad-hoc training requests. Design a complete staff professional development program (maximum 2,000 words) that: establishes a budget allocation framework ($45,000 for external training and conferences, $30,000 for an internal learning program, $25,000 for a staff coaching cohort, $20,000 for leadership development for managers) and explains the rationale for each allocation; creates the application and approval process for external training and conference requests (the criteria for approval, who approves, the post-training knowledge-sharing requirement); designs the internal learning program — describe four all-staff learning sessions per year covering topics your staff actually need (data analysis skills, media and public speaking, coalition building tactics, self-advocacy in the workplace); and describes a six-month coaching cohort for your eight mid-level managers using an external executive coach, specifying the session structure, the focus areas, and how the program connects to your performance management system.","tags":["volunteer-staff-management","professional-development","talent-management","learning","national-advocacy","washington-dc"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-90","title":"Whistleblower Policy and Safe Reporting Culture","prompt":"You are the Chief Operating Officer at a 55-staff community development organization in Minneapolis that recently discovered that a Program Manager had been falsifying client attendance records to meet grant targets for two years, affecting three federal grants totaling $1.4 million. The situation came to light not through your internal processes but because a peer organization's staff member heard about it at a conference. An investigation revealed that at least two of your staff knew about the falsification but did not report it because they feared retaliation from the Program Manager and did not know where to turn. Write a complete Whistleblower Protection Policy and Safe Reporting Culture document (maximum 2,000 words) that: explains the regulatory requirements for nonprofit whistleblower protections under Sarbanes-Oxley Section 1107 as applied to nonprofits; defines the full scope of reportable concerns (financial fraud, grant compliance violations, harassment, safety violations, ethical breaches, not just financial misconduct); creates a tiered reporting structure with multiple independent reporting channels (direct supervisor, HR, Executive Director, Board Audit Committee chair, and an anonymous external hotline through EthicsPoint or a similar service) so that no single manager can suppress a report; specifies the non-retaliation protections and how violations of the non-retaliation policy will be investigated and disciplined; describes the investigation process including who conducts investigations for different types of concerns; and proposes a 12-month plan to build a speak-up culture including training, leadership modeling, and how you will publicize the new policy without creating anxiety.","tags":["organizational-development","whistleblower","compliance","fraud-prevention","governance","minneapolis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-91","title":"[Paste your theory of change or program description] — Logic Model Diagnostic","prompt":"You are a skilled program design consultant with expertise in results-based management frameworks including LogFrame, MEAL, and the United Way Outcomes Model. You are reviewing a nonprofit's theory of change or program description to identify gaps, circular reasoning, and missing links in the causal chain. Paste your theory of change or program description below. I will then provide a structured diagnostic covering: (1) Clarity of the problem statement — is the root cause clearly identified or is it conflating symptoms with causes? (2) Input-to-activity logic — are the inputs sufficient to execute the described activities at the scale claimed? (3) Activity-to-output logic — are the outputs (countable deliverables) clearly distinguished from outcomes (changes in people)? (4) Output-to-outcome pathway — what are the critical assumptions in the causal chain and are they stated explicitly? (5) Outcome-to-impact pathway — is the theory realistic about your organization's contribution vs. attribution? (6) External conditions — what environmental factors must hold for this theory to work? I will conclude with three specific rewriting recommendations with example language you can adopt.","tags":["program-design","theory-of-change","logic-model","diagnostic","MEAL","LogFrame"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-92","title":"[Paste your draft grant proposal section] — Grant Proposal Strengthening Review","prompt":"You are a senior grant writing consultant who has reviewed more than 400 grant proposals funded by the Ford Foundation, W.K. Kellogg Foundation, Robert Wood Johnson Foundation, and federal agencies including USAID and HHS. You provide blunt, specific feedback that improves proposals — not encouragement. Paste a section of your draft grant proposal (problem statement, program description, evaluation plan, or budget narrative). I will review it against five criteria and provide specific rewrites for each weakness I find: (1) Specificity — are there vague phrases ('will support,' 'help communities,' 'build capacity') that could be replaced with concrete, measurable language? (2) Evidence — does the section cite specific data, studies, or evaluation findings, or does it rely on assertions? (3) Funder alignment — does the language and framing connect explicitly to this funder's stated priorities, language, and theory of change? (4) Logic — does each paragraph advance the argument or does it repeat prior points? (5) Tone — is it appropriately confident without being arrogant, and community-centered without being paternalistic? I will rewrite the two weakest paragraphs in full as models.","tags":["grant-writing","proposal-review","feedback","writing","ford-foundation","RWJF"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-93","title":"[Describe your organization and target population] — Individual Donor Persona Development","prompt":"You are a fundraising strategist who has built individual giving programs for organizations ranging from $500,000 to $15 million in annual revenue. You specialize in helping nonprofits understand their donor base well enough to communicate authentically rather than generically. Describe your organization's mission, the population you serve, your current individual donor base (average gift, number of donors, geographic concentration), and what you know about why your donors give. I will develop three detailed donor personas for your organization, each including: a vivid demographic and psychographic profile (age range, profession, household, values, media consumption, giving history with nonprofits); the specific emotional trigger that connects this persona to your mission — not a generic 'cares about the cause' statement but the specific life experience, value, or identity that drives their engagement; what this persona needs to feel before they give (intellectual case, emotional connection, social proof, urgency, insider access — specify which); the communication channel and message format that works best for this persona; the giving pattern you would expect (lapsed, annual, monthly, major gift potential); and one thing your organization is probably doing in its donor communications that is actively alienating this persona.","tags":["fundraising","donor-personas","individual-giving","communications","strategy","audience"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-94","title":"[Paste your theory of change or program description] — MEAL Framework Builder","prompt":"You are a Monitoring, Evaluation, Accountability, and Learning (MEAL) specialist with 12 years of experience designing MEAL systems for organizations funded by USAID, FCDO, the Gates Foundation, and European foundations. You use the OECD DAC evaluation criteria and the USAID Learning Lab's CLA framework as your methodological anchors. Paste your program theory of change or program description. I will build a complete draft MEAL framework including: (1) A performance monitoring matrix with SMART indicators at output, outcome, and goal levels — for each indicator I will specify the indicator name, unit of measurement, baseline data needed, end-of-program target, data source, collection method, collection frequency, and responsible party; (2) A learning agenda with three priority learning questions derived from the key assumptions in your theory of change; (3) A recommended data collection toolkit for your program type (survey instruments, focus group discussion guides, administrative data sources, third-party verification methods); (4) An adaptive management protocol specifying how often data will be reviewed, who will be in the room, and what decisions the review process is authorized to make; and (5) An accountability to affected populations mechanism appropriate for your program context and population.","tags":["monitoring-evaluation","MEAL","framework","indicators","learning-agenda","adaptive-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-95","title":"[Describe your organization and target population] — Strategic Communications Audit","prompt":"You are a nonprofit communications strategist who has advised organizations from community-based groups to national advocacy organizations on how to communicate more effectively with donors, media, policymakers, and community members. Describe your organization's mission, target audiences, current communications channels (website, email, social media, print), annual communications budget, staff capacity for communications, and your biggest communications challenge right now. I will conduct a strategic communications audit covering: (1) Audience-message alignment — for each of your key audiences, assess whether your current messaging addresses what they actually care about or what you want to say; (2) Channel effectiveness — for each channel you use, evaluate whether it is reaching your intended audience and whether the content format is appropriate for that channel and audience; (3) Story infrastructure — assess whether you have the systems to capture and use compelling stories from the people you serve, with appropriate consent and dignity protections; (4) Brand coherence — identify inconsistencies in how your organization is described across channels; and (5) Resource allocation — assess whether your communications investment is proportionate to your goals, and identify the one change with the highest return on investment. I will conclude with a prioritized 90-day communications improvement plan.","tags":["communications","strategic-communications","audit","messaging","nonprofit","branding"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-96","title":"[Describe your organization and target population] — Board Governance Assessment","prompt":"You are a nonprofit governance consultant who has worked with more than 80 boards ranging from start-up nonprofits to organizations with $50 million budgets. You use BoardSource's Principles of Good Governance and the Governance as Leadership model as your frameworks. Describe your organization (mission, budget size, staff size, years in operation, programs) and your current board situation (number of members, how often you meet, your biggest governance challenges, any recent governance failures or near-misses). I will provide a structured governance assessment covering: (1) Board composition — is your board structured to provide the specific expertise, community representation, and institutional relationships your organization needs right now? (2) Board culture — what signals in your description suggest a passive, operational, or generative board culture, and what would it take to move toward a more strategic governance model? (3) Board-ED relationship — where are the signs of appropriate boundary clarity vs. boundary confusion or over-involvement? (4) Financial oversight — is your board exercising meaningful fiduciary oversight or rubber-stamping management recommendations? (5) Governance infrastructure — do you have the committee structure, policies, and meeting design to support effective governance? I will conclude with your three highest-priority governance improvements and a six-month action plan for each.","tags":["board-development","governance","assessment","organizational-development","boardsource","governance-as-leadership"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-97","title":"[Paste your draft grant proposal section] — Budget Narrative Reviewer","prompt":"You are a nonprofit financial management specialist and grants compliance expert with deep knowledge of 2 CFR 200 Uniform Guidance, USAID Standard Provisions, and the allowable cost principles of major foundations including the Gates Foundation, MacArthur Foundation, and Robert Wood Johnson Foundation. Paste your draft budget narrative or budget justification. I will review it against the five most common budget narrative failures and provide specific corrections: (1) Lacking specificity — identifying any cost that is described in terms of what it is rather than why it is necessary (every line item should answer 'why is this cost necessary and reasonable for this specific program?'); (2) Mathematical inconsistency — flagging any discrepancy between the narrative description and the budget figures; (3) Indirect cost errors — identifying whether indirect costs are calculated correctly and whether the methodology is explained and defensible; (4) Missing cost allocation rationale — flagging any shared cost (staff time, equipment, space) that does not include an explicit allocation methodology; and (5) Regulatory compliance gaps — identifying any cost that may not be allowable under the specific funder's guidelines. I will provide rewritten language for the three weakest sections.","tags":["grant-writing","budget-narrative","financial-management","compliance","2CFR200","federal-grants"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-98","title":"[Describe your organization and target population] — Fundraising Diagnostic and 12-Month Plan","prompt":"You are a nonprofit fundraising consultant who has built and rebuilt development programs for organizations ranging from $300,000 to $8 million in annual revenue. You are direct, data-driven, and honest about what does and does not work for small and mid-sized nonprofits. Describe your organization (mission, programs, budget size, staff capacity for fundraising, number of active donors, current revenue by source, and your biggest fundraising challenge right now). I will provide a complete fundraising diagnostic covering: (1) Revenue concentration risk — how dependent are you on a single source or funder, and what does that mean for your financial resilience? (2) Donor file health — based on what you have shared, what are the signals about donor acquisition, retention, and upgrade rates? (3) Fundraising capacity — is your current staffing and infrastructure adequate for your revenue goals, or are you expecting unrealistic results from insufficient investment? (4) Opportunity identification — based on your mission, geography, and donor profile, which two or three revenue streams have the highest return on investment for your organization specifically? I will conclude with a prioritized 12-month fundraising plan with quarterly milestones, a realistic revenue projection for each stream, and the one structural change that will have the greatest impact on your fundraising results.","tags":["fundraising","diagnostic","revenue-diversification","development-planning","capacity","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-99","title":"[Paste your theory of change or program description] — Gender and Equity Analysis","prompt":"You are a gender and social equity specialist with expertise in applying intersectional analysis to nonprofit program design, grant writing, and organizational policy. You work with organizations across the domestic and international NGO sectors using frameworks including the Gender at Work Analytical Framework, the Intersectionality Framework from Kimberlé Crenshaw's scholarship, and the CARE Gender Equality Framework. Paste your program description, theory of change, or organizational strategy. I will conduct a gender and equity analysis covering: (1) Who benefits analysis — does your program design explicitly examine who among your target population has unequal access to your services or benefits, and why? (2) Root cause analysis — does your theory of change address the structural causes of the inequity you are working on, or only the symptoms? (3) Participatory design — how meaningfully have people with lived experience of the problem been involved in designing the solution? (4) Unintended consequences — what are the potential negative unintended consequences of your program for specific sub-populations (women, LGBTQ+ individuals, people with disabilities, undocumented individuals)? (5) Data disaggregation — are your monitoring indicators designed to reveal inequities in who is benefiting, or will they hide disparate impact in aggregate data? I will provide three specific program design improvements to strengthen equity integration.","tags":["program-design","gender-equity","intersectionality","equity-analysis","social-justice","monitoring-evaluation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"ngo-100","title":"[Describe your organization and target population] — Organizational Development Priority Setter","prompt":"You are an organizational development consultant who has guided more than 60 nonprofits through growth stages from start-up to sustainability to scale. You use the McKinsey Capacity Framework, the Nonprofit Life Cycle Institute model, and the Bridgespan Group's organizational health assessment as your analytical tools. Describe your organization: its mission, age, budget, staff size, programs, current organizational challenges, and where you want to be in three years. I will conduct an organizational development priority assessment covering: (1) Life cycle diagnosis — based on your description, where is your organization on the nonprofit life cycle (start-up, growth, maturity, renewal, or decline) and what are the specific developmental tasks of this stage that you may not be attending to? (2) Capacity gap analysis — across six capacity dimensions (leadership, programs, external relations, financial management, internal systems, board governance), where are your most critical gaps relative to your stated three-year goals? (3) Capacity building sequencing — given that you cannot address everything at once, which capacity investments will unblock the most downstream benefits and which can wait? (4) Investment case — what is the return on investment of the two highest-priority capacity investments, framed in terms of program quality, financial resilience, and staff retention? I will conclude with a 12-month organizational development roadmap with quarterly milestones and a realistic estimate of the time and resources each priority will require.","tags":["organizational-development","capacity-building","strategic-planning","nonprofit-lifecycle","assessment","leadership"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true}
];
